(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["5-1"] = [{"a": [1], "v": 4, "p": 253, "ev": 4, "ep": 254, "sid": 1745, "t": "وقوله: ﴿غَيۡرَ مُحِلِّي ٱلصَّيۡدِ﴾⟪5:1⟫ معناه كلوا ذلك على أن لا يكون صيدا في حال الإحرام،\n⟦4:254⟧\nوقوله تعالى: ﴿إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ﴾⟪5:1⟫ الحكمة، والحكمة من أصل الإبانة إذا كان في القول قيل: له حكم وقد حكم، وإذا كان في الفعل، قيل: له حكمة وحكم وله حكم فإذا قلت: حكمت بكذا، فمعناه قضيت فيه بما هو حكمه، وإن كان يقال حكم فلان بالباطل، بمعنى أجرى الباطل مجرى الحكمة، فحكم الله تعالى مقتض للحكمة لا محالة فنبه بقوله: ﴿إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ﴾⟪5:1⟫ أن ما يريده يجعله حكمه حثا للعباد على الرضا به كما قال عليه الصلاة والسلام: حاكيا عن ربه تعالى: (من لم يرض بقضائي ولم يصبر على بلائي فليطلب ربا سواي).\nفالله يحكم ما يريد، وحكمه ماض ومن رضي بحكمه استراح في نفسه، وهدي لرشده، ومن سخط نقد حكمه واكتسب بسخطه سخط الله وإمقاته."}, {"a": [2], "v": 4, "p": 254, "ev": 4, "ep": 261, "sid": 1746, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام يبتغون فضلا من ربهم ورضوانا وإذا حللتم فاصطادوا ولا يجرمنكم شنئان قوم أن صدوكم عن المسجد الحرام أن تعتدوا وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان واتقوا الله إن الله شديد العقاب (2)\n⟦4:255⟧\nالشعائر: حمع شعيرة أي العلامة، وأصلها إصابة\nالشعر، كقولك عانه وكبده، يقال للحواس المشاعر، قال الحسن: شعائر\nالله دينه وفرائضه، وقول عطاء: هي مناسك الحج، فأشار إلى نحو ما قال\nالحسن.\nوقوله: ﴿وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ﴾⟪5:2⟫ أي القتال فيه وقيل: هو تحريم\nالنسىء المذكور في قوله: ﴿إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ﴾⟪9:37⟫.\n⟦4:256⟧\nوالهدي أصله فيما يهدى من النعم، وقد يستعمل في كل ما يتقرب به إلى الله\nوعلى ذلك قال عليه الصلاة والسلام: (المبكر للجمعة كالمهدي بدنه، إلى أن قال ثم الذي يليه كالمهدي بيضة)، فجعل البيضة هديا.\nوالقلائد ما يطوق به الهدي شعارا له، وقيل: نبه بذلك على تحريم كل ما يحتص بالهدي فنص على أدناه الذي لا قدر له تنبيها على ما فوقه، كقوله تعالى: ﴿مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ﴾\nوقيل: أراد به المقلدات فبين تحريم المقلد وغير المقلد\n⟦4:257⟧\nوقال بعضهم معنى: ﴿لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ﴾⟪5:2⟫: أي لا تمنعوا الكفار من\nالتمسك بشعائره، فقد كانوا مجتمعين مع المؤمنين في إقامة\nالمناسك فمن قال هذا قال الآية منسوخة لقوله:\n﴿فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ﴾⟪9:5⟫.\nوعلى الأول خطاب للمسلمين لمراعاة أحكام الدين عاما، أو أحكام الحج، ولا يكون فيه نسح،\nوقوله: ﴿يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ﴾⟪5:2⟫\nقيل: عنى الفضل الدنيوي المطلوب بالمكاسب المباحة.\nوقيل: بل الفضل الأخروي.\n⟦4:258⟧\n﴿وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ﴾⟪5:2⟫ رخصة كقوله: ﴿فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ﴾⟪62:10⟫ ليجزم أن التكسب مكروه، ولا يقال ذلك للكسب المحمود في عامة كلامهم.\nوقول الشاعر:\nجريمة ناهض في رأس نيق -\nعلى طريق التشبيه. والتنبيه أن العقاب يرتكب بالجرائم، لا قبل أدائها\n⟦4:259⟧\nكما ذكر بعض الحكماء ما ذو والد وإن كان بهيمة إلا ويذنب لأجل أولاده\nوعلى هذا المعنى قيل: فلان يجرم لأهله، وقوله تعالى: ﴿أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾⟪5:2⟫ أي لأجل أن صدوكم.\nوقولهه: (أن تعتدوا) أي على أن تعتدوا، ونهى المسلمين عن الاعتداء على من ظلمهم فأبغضوهم لظلمهم إياهم، وقرأ إن صدوكم، ويكون في تقدير المستقبل.\nإن قيل كيف قال هاهنا هذا، وقد قال: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ﴾⟪2:194⟫ قيل الأمور به في قوله: ﴿فَٱعۡتَدُواْ عَلَيۡهِ﴾⟪2:194⟫ إباحة المجازاة للظالم بمثل فعله فسماه باسم الأول.\nوقوله تعالى: ﴿أَن تَعۡتَدُواْۘ﴾⟪5:2⟫ نهى عما هو أكثر من المجازاة، أو حث على العفو، وقوله:\n(شنئان) إذا قرأ بفتح النون فمصدر، نحو نزوان وطيران، وإذا قرأ\n⟦4:260⟧\nبسكونها فاسم، نحو عطشان أي لا يحملنكم بغيض قوم، أي من يبغضون\nمنهم.\nوقيل: شنآن وشنآن. بمعنى وأكثر ما يقال في المصادر، والأوصاف\n، والأفعال التعدية.\nوالتقوى في هذا الموضع اسم لغاية ما يبلغه الإنسان وهي\nالمذكورة في قوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾ فكأنه قال تعاونوا على أدنى المنازل من\nالخير وأقصاها، وقيل: بل البر أعلى المنزلتين فإنه ما اطمأن إليه القلب من غير أن ينكره بجهة أو سبب، والتقوى: اجتناب المآثم، فكأنه قيل تعاونوا على فعل الخير وترك الشر.\nوقوله تعالى: ﴿وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ﴾⟪5:2⟫ فالإثم يتناول جنايات العبد بينه وبين الله وما بينه وبين العباد.\n⟦4:261⟧\nوالعدوان ما بينه وبين غيره وهو أخص، وعقب ذلك بقوله: ﴿وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ﴾⟪5:2⟫. زجرا عما نهى عنه."}, {"a": [3], "v": 4, "p": 261, "ev": 4, "ep": 270, "sid": 1753, "t": "قوله تعالى: (حرمت عليكم الميتة والدم ولحم الخنزير وما أهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم وما ذبح على النصب وأن تستقسموا بالأزلام ذلكم فسق اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا فمن اضطر في مخمصة غير متجانف لإثم فإن الله غفور رحيم (3)\n(الميتة) هاهنا ما فارقته الروح من غير تذكيه مما له نفس سائله، وقد يقال: ذلك لما ليس له نفس سائله، كقوله عليه الصلاة والسلام: (أحل لنا@ ميتتان ودمان)، (والدم) هاهنا هو\n⟦4:262⟧\nالدم المسفوح بدلالة قوله ﴿قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ﴾⟪6:145⟫ فعرف في الآية الدم ولحم الخنزير، وإشارة إلى ما ذكره هاهنا.\nوتخصيص لحم الخنزير لا يقتضي تحليل شحمه وسائر ما فيه لأن ذلك نص على أفضل ما فيه ليدل على ما دونه.\nوقال بعض الفقهاء: لا يجوز الانتفاع\n⟦4:263⟧\nبثمنه، ولا باستعمال شيء منه في غير الأكل والإهلال: التكبير: من قولهم\nأهل الصبي كأن الصبي يكبر الله فعلا، وإن لم يكبره قولا؛ لدلالته على\nالآية، كتسبيح الشجر والمدر فعلا وإن لم يكن تسبيحه قولا، فحرم ما سمي\nعند ذبحه الأصنام، (والمنخنقة) ما وقع في حلقه ما خنقه حبلا كان\nأو غيره، (والموقوذة): المقتولة بضرب، يقال: وقذته\nضربا، ويدخل فيه كل مقتول بغير ذكوه، فأما المرمي من الصيد بما يخرج بحدة فغير داخل في الموقوذة، بدلالة قوله عليه الصلاة والسلام:\n(إذا رميت بالمعراض وذكرت اسم الله فأصاب وخرق فكل، فإن أصابه بعرض فلا يحل فإنه وقيذه).\n⟦4:264⟧\n(والمتردية) الساقطة من سطح أو جبل أو في بئر يؤدي\nسقوطها إلى أذاها.\n(والنطيحة) المقتولة بالنطاح، ناطحة كانت أو منطوحة.\n﴿وَمَآ أَكَلَ ٱلسَّبُعُ﴾⟪5:3⟫ مما افترسه سبع فمات.\nوقوله: ﴿إِلَّا مَا ذَكَّيۡتُمۡ﴾⟪5:3⟫ راجع إلى المنخنقة وما بعدها.\nوإدراك ذكاته هو أن تؤخذ له عين تطرف أو ذنب يحرك.\nعلى ما روي عن أمير المؤمنين، والذكاة:\n⟦4:265⟧\nبقطع الحلقوم، والمريء ومستحب أن تقطع معهما الودجين،\nو (النصب) حجر كانوا ينصبونه ويتقربون بالذبائح له، والاستقسام بالأزلام هو ما كانوا يفعلونه في الميسر، كقوله: ﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ﴾⟪5:90⟫.\nفإن قيل ذكر (ما) في قوله ﴿وَمَآ أُهِلَّ﴾⟪5:3⟫ (وما ذبح)، وذكر هاهنا (أن تستقسموا) دون (ما)؟\nقيل: لأن المحرم في الأول نفس المذبوح، والمحرم هاهنا الاستقسام فأما المذبوح على الشريطة المشترطة في الشرع فإنه وإن قسم بالأزلام لا يحرم عينه.\nوقيل: الأزلام قداح تكتب على بعضها أمرني ربي وعلى بعضها نهاني ربي فإذا أرادوا أمرا\n⟦4:266⟧\nضربوا ذلك فاعتبروا ما يخرج منه.\nوالفسق والفجور: هما الخروج عن أمر الله\nفالفسق من قولهم فسقت الرطبة من قشرها.\nوالفجور من فجر الماء،\nوقوله: ﴿ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ﴾⟪5:3⟫ أي أن لا يحققوا أن لا يمكنهم\nأن ينسخوا ما أمرهم من دين الحق.\nوقوله تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫ قيل: لما كان الإسلام شرع شيئا منشئا بين تعالى بهذه الآية كماله، وقيل: إن الأديان الحق كلها جارية مجرى دين واحد وكان قبل الإسلام في الشيء بين إفراط وتفريط بالإضافة إلى شرعيتها، وذلك على حسب ما كان يقتضي حكمة الله في كل زمان فكمله الله تعالى بالنبي - صلى الله عليه وسلم -، وجعله وسطا مصونا\nعن الإفراط والتفريط، كما قال: ﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾⟪2:143⟫\nوكمله وتممه به كما قال عليه الصلاة والسلام: (بعثت لأتمم مكارم\nالأخلاق).\nوقال: (إن مثل الأنبياء كمثل بيت ترك بينه موضع لبنة فكنت اللبنة).\n⟦4:267⟧\nفهذا معنى قوله: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫\nوهذا هو الذي اقتضى أن تكون شريعته مؤبدة لا نسخ ولا تغيير، فالأشياء في التغيير والتنقل ما لم تكمل فإذا كملت فتغيرها فساد لها، ولهذا قال: ﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ﴾⟪10:32⟫ ونبه بقوله: ﴿وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ﴾⟪5:3⟫\nعلى أمرين: أحدهما: أن الإسلام هو الدين المرتضى على الإطلاق\nلا تبديل له ولا تغيير، وسائر الأديان مثله كان مرتضى في وقت دون\nوقت، وعلى وجه دون وجه، والقوم دون قوم، وهذا الدين بعد أن شرع\nمرتضا في كل وقت، ولهذا قال عليه الصلاة والسلام في موسى: (لو كان حيا ما وسعه إلا اتباعي) ولأجل ذلك قال تعالى:\n⟦4:268⟧\n﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ﴾⟪3:85⟫.\nوقال: ﴿هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ﴾ الآية. فقوله تعالى: (اليوم) إشارة إلى زمان النبي - صلى الله عليه وسلم -\nأو إشارة إلى اليوم الذي أنزلت هذه السورة. فقد كان في النسىء في زمن\nالنبي - صلى الله عليه وسلم - أيضا إلى آخر أيامه، فحينئذ كمل وصار بحيث لا تغيير فيه ولا تبديل بنسخ ونسخ.\nإن قيل: كمل الدين النبي - صلى الله عليه وسلم -، وقد حكم تعالى أن دينه هو دين إبراهيم حيث قال: ﴿مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا﴾⟪22:78⟫. قيل: ونبه تعالى أن هذا الدين الذي هو دين إبراهيم من\nحيث أنهما داعيان إلى الحق ومشتركان في أصول الشريعة، لكن ما شرع على\n⟦4:269⟧\nلسان إبراهيم كان مبدأ الإسلام، وما شرع على لسان محمد - صلى الله عليه وسلم - خاتمة الإسلام.\nفمن حيث إن هذا مؤيد ناسخ لفروع ما تقدم قال: ﴿لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ﴾ ومن حيث إنه شارك دين إبراهيم في الأصول صار هو إياه، وهذا ظاهر\nلمن عرف قوانين الكلام.\nإن قيل: إن ذلك يقتضي أن يكون الأديان كلها\nناقصة، وأن يكون دينه عليه الصلاة والسلام قبل ذلك اليوم ناقصا.\nقيل: الكامل والناقص من الأسماء المتضايفة التي تقال باعتبار بعضها بعض، فالصبي إذا اعتبر بالرجل فهو غير كامل، وإذا اعتبر بمن هو على سنه فهو كامل، إذا لم يكن مذموما فكذلك دين الأنبياء قبل النبي - صلى الله عليه وسلم - إذا اعتبر بأهل زمانهم كان كاملا، وإذا اعتبر بدين النبي - صلى الله عليه وسلم - وزمانه لم يكن كاملا وليس النقصان المستعمل هو النقص\nالمذموم فلفظة ناقص تستعمل على وجهين.\nإن قيل: ما وجه فائدة قوله تعالى: ﴿وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ﴾⟪5:3⟫\nبعد قوله: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫؟\nقيل لما بين تعالى أنه أكمل دينهم بين بعده أن ذلك الدين هو الإسلام\nوقد رضيته كما قال تعالى: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾⟪3:19⟫.\nوقوله: ﴿وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي﴾⟪5:3⟫ أضاف النعمة إلى نفسه تشريفا لها.\nوقوله: ﴿فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ﴾⟪5:3⟫ منه أن الخشية في الحقيقة يجب أن تكون ممن\nمنه مبدأ النفع والضر دون الوسائط فقد قيل: أعجز الناس من خشي من\n⟦4:270⟧\nلا ينفعه ولا يضره، دون الذي بيده الخير.\nوقوله تعالى: ﴿فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ﴾⟪5:3⟫ أي من ناله ضرورة ولم يجنف، أي: لم يمل لما تبين إثما بل راعى الحق وقصد دفع أذى الجوع. فالله تعالى لا يؤاخذه به فإنه كان غفورا لذنوب عباده رحيما بهم.\nفهو أهل أن لا يؤاخذهم بما فسح لهم\nفيه وعلى نحو هذه الآية دل قوله تعالى: ﴿فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ﴾⟪2:173⟫."}, {"a": [4], "v": 4, "p": 270, "ev": 4, "ep": 276, "sid": 1762, "t": "قوله عز وجل: (يسألونك ماذا أحل لهم قل أحل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما أمسكن عليكم واذكروا اسم الله عليه واتقوا الله إن الله سريع الحساب (4)\nالطيب التام الذي يستلذ عاجلا وآجلا، وذلك هو الحلال\nالذي لا يعقب إثما، وقوله:\n⟦4:271⟧\n﴿وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ﴾⟪5:4⟫ مبتدأ. وقوله: (فكلوا) في موضع الخبر.\nقال بعضهم: هو معطوف على الطيبات وتقديره: صيدوا ما علمتم، والأول أجود، والجوارح: الصائدات الكاسبات من الكلاب والفهود ونحوها بالجرح بناب أو مخلب، ومنها قيل جرح فلان واجترح إذا اكتسب، والمكلب: المضري على الصيد سواء أضرى كلبا أو غيره.\nوبعض المفسرين خص ذلك بالكلب وكره صيد جوارح الطير إذا قتلت، وقال إن ذلك لا يستعمل فيه التكليب.\nومن شرط المعلم أنه إذا دعي أجاب وأن لا يأكل من الصيد ومتى\n⟦4:272⟧\nكان ذلك فإنه يؤكل وإن قتله، وقال الكوفيون: صيد جوارح الطير\nيؤكل منه، وإن أكل.\nوقول النبي - صلى الله عليه وسلم -: (إذا سميت فكل وإن أكل منه فلا\nتأكل) يقتضي خلاف ما قالوه، ومعنى:\n⟦4:273⟧\n﴿فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ﴾⟪5:4⟫\n⟦4:274⟧\nإشارة بقوله: (أمسكن) أن لا يأكلن.\nوظاهر الآية أن لا فرق\n⟦4:275⟧\nبين كلب المجوسي والمسلم إذا أرسله المسلم، بخلاف ما قال الثوري: أنه\nيكره الاصطياد بكلب المجوسي، وأجمعوا أنه إذا قدر على ذبح ما أمسكه\nالمكلب فلم يذبح فلا يؤكل، وقوله: ﴿إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ﴾⟪5:4⟫\n⟦4:276⟧\nقال ابن عباس: يعني لأوليائه، وجعل ذلك أمنا لهم، وقال: بل ذلك تخويف لمن خالف أمره."}, {"a": [5], "v": 4, "p": 276, "ev": 4, "ep": 281, "sid": 1768, "t": "قوله عز وجل: (اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم والمحصنات من المؤمنات والمحصنات من الذين أوتوا الكتاب من قبلكم إذا آتيتموهن أجورهن محصنين غير مسافحين ولا متخذي أخدان ومن يكفر بالإيمان فقد حبط عمله وهو في الآخرة من الخاسرين (5)\nيعني اليوم ما تقدم ذكره في قوله: ﴿ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ﴾⟪5:3⟫\nوفي قوله: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫ وذلك إشارة إلى\nعام الوداع.\n﴿ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪5:5⟫ عند الشافعى: - هم\n⟦4:277⟧\nبنو إسرائيل من اليهود والنصارى دون من دخل في دينهم بعد الإسلام، لقوله: ﴿وَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ﴾⟪45:16⟫.\nوقال ابن عباس: فهم الصابئون.\nوروي عن علي: أنه لا تحل ذبائح النصارى العرب.\nوعند أبي حنيفة: أن ذلك يتناول أيضا من يدخل بعد الإسلام في\n⟦4:278⟧\nدينهم احتجاجا بقوله تعالى: ﴿لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ﴾⟪5:51⟫ فحكم\nأنهم منهم. ويعني بطعامهم ما يذبحونه ويتولون الصنعة، ومما يملكونه، ولم\nيحتج أن يشترط فيه رضا مالكه إذا لم يكن القصد إلى ذلك وقوله:\n﴿وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ﴾⟪5:5⟫ أي يجوز أن تطعموهم،\nوقوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪5:5⟫ أي العفائف، وقال\n⟦4:279⟧\nالشافعي: عنى الحرائر منهم، ومنع الحر من التزوج بإمائهن، ويقوي قوله\n: ﴿وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ﴾⟪4:25⟫.\nوكان ابن عمر رضي الله عنه: يكره التزوج بالكتابيات\nوإذا سئل عن ذلك يقرأ هذه الآية قوله: ﴿وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ﴾⟪2:221⟫ ويقول في قوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ﴾⟪5:5⟫ أي من الذين كانوا منهم فأسلموا كقوله: ﴿مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ﴾⟪3:113⟫ وغيره\nحمل قوله: ﴿وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ﴾⟪2:221⟫ على أهل الأوثان والمجوس\n⟦4:280⟧\nوقال ابن عباس: لا لمجل نكاح الحربيات منهن لقوله: ﴿قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾⟪9:29⟫ إلى قوله: ﴿وَهُمۡ صَٰغِرُونَ﴾\nوأكد ذلك بقوله: ﴿لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ﴾⟪58:22⟫.\nوالنكاح يقتضي المودة لقوله: ﴿خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ﴾⟪30:21⟫.\nوقال: من جوز التزوج منهن أن المودة المنهي عنها هى المودة الدينية، وأما المودة الزوجية فهي التبقية، وذلك غير محظور.\nقوله: ﴿وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ﴾⟪5:5⟫ أي بالدين الحق.\nوالحبط أصله الحبط وهو داء يأخذ الإبل في أجوافها من كلأ يستوبله.\nوقيل معناه: من\n⟦4:281⟧\nلم يشكر الله بالإيمان، أي هو ذو إيمان فقد حبط عمله تنبيها أن الاعتقاد لا يكفى ما لم يضامه شكر نعمه بإقامة عباداته.\nوقيل معناه: من لم يراع حقيقة الإيمان بالاعتقاد لم تنفعه أعماله."}, {"a": [6], "v": 4, "p": 281, "ev": 4, "ep": 289, "sid": 1773, "t": "قوله عز وجل: (يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برءوسكم وأرجلكم إلى الكعبين وإن كنتم جنبا فاطهروا وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط أو لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون (6)\nقال أصحاب أبي حنيفة: ظاهر الآية تقتضي أن لا يجب في\nالوضوء النية، والقول بوجوبه يقتضي زيادة في النص والزيادة في النص تقتضي النسخ، ونسخ القرآن لا يجوز اتفاقا بخبر الواحد والقياس فلا يصح إذا إثبات النية، وقال بعض الشافعية: بل الآية تقتضي إيجاب النية لأن معنى\n⟦4:282⟧\nقوله: ﴿إِذَا قُمۡتُمۡ﴾⟪5:6⟫ إذا أردتم ولو لم يكن معناه ذلك لم يكن لذكره فائدة.\nوقال بعضهم: الآية تقتضى الترتيب، لأن الفاء في قوله: (فاغسلوا)\nتقتضي ترتيب غسل الوجه على القيام، فإذا ثبت ترتيب الوجه على القيام ثبت في غيره لأن أحدا لم يفصل، وليس ذلك بشىء فإن الفاء وإن كانت تقتضي الترتيب فإنما اقتضى ذلك في الجملة لا في البعض، ولم يقتضي ترتيب الأعضاء والمأمور بغسلها بعضا على بعض، والأظهر أن الترتيب اقتضتاه قول النبي\n- صلى الله عليه وسلم -: (ابدأوا بما بدأ الله به) وفعله الذي فعله تبيانا للآية، وقد رنب ثم قال:\n(هذا وضوء لا يقبل الله الصلاة إلا به)،\nوالمرفقان داخلان في الغسل بدلالة\n⟦4:283⟧\nما روي من الأخبار، وظاهر الآية تقتضي مسح الرجل لولا ما روي في ذلك\nمن الأخبار سواء قرئ بالنصب أو بالجر، وذاك أنه إذا نصب فهو كقوله\n⟦4:284⟧\nمررت بزيد وعمروا، وروي أن النبي - صلى الله عليه وسلم - كان يتوضأ لكل صلاة، فلما كان يوم فتح مكة مسح على خفيه وصلى الصلوات بوضوء واحد، فقيل له: في ذلك.\nفقال: (عمدا فعلت) وظاهر أول الآية أن كل صلاة تقتضي الطهارة لكن لما\nشرط في البدل وهو التيمم فقال: ﴿أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ﴾⟪5:6⟫ علم أن ذلك شرط في المبدل أيضا، ولأن الإجماع\nعلى أنه لا يجب الوضوء لكل صلاة ما لم يحصل حدث وقد استحب تجديد\nالوضوء لكل صلاة من أجل ظاهر اللفظ، ولأن النبي - صلى الله عليه وسلم - قال: (الوضوء على الوضوء نور على نور)،\nوقال: (لولا أن أشق على أمتي لأمرت في كل صلاة بالوضوء).\n⟦4:285⟧\nوقوله: ﴿وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ﴾⟪5:6⟫ وهوكقوله:\n﴿وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ﴾⟪4:43⟫ والجنابة بإنزال الماء\nأو بالتقاء الختانين، وقوله: (فاطهروا) أي تطهروا فأدغم فسكن تاء\nالفعل وأدخل عليه ألف الوصل.\nوقوله: ﴿وَإِن كُنتُم مَّرۡضَىٰٓ﴾⟪5:6⟫ أي مرضا يمنع من استعمال الماء ﴿أَوۡ عَلَىٰ سَفَرٍ﴾⟪5:6⟫ أي سفرا يعدم فيه الماء وظاهر اللفظ يقتضى قليل السفر وكثيره ولكن الأخبار خصته.\n⟦4:286⟧\nوملامسة النساء كناية عن الجماع عند عامة الصحابة، وذكر عن ابن عمر: آية اللمس بأي موضع كان من البدن، وإليه ذهب الشافعي، وقال قوله: ﴿فَلَمۡ تَجِدُواْ مَآءٗ﴾⟪5:6⟫ يقتضي أن يطلب، لأن عدم الوجود يقتضي الطلب، وظاهر\nالآية تقتضي أن لا يجوز التيمم إلا بعد عدم قليل الماء وكثيره، ومستعمله وغير\n⟦4:287⟧\nمستعمله لكن استثنى المستعمل، بدلالة قوله تعالى: ﴿وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا﴾⟪25:48⟫ ولا خلاف أن ذلك يقتضى الماء المطلق، إلا عند الأصم، فإنه\nأجاز التوضؤ بماء الورد وما يجري مجراه في الرقة،\nوقوله: ﴿فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا﴾⟪5:6⟫ أي ترابا.\nوقيل: وجه الأرض، وإن لم يكن عليه التراب، وقوله: (منه) يقتضي ما قاله الشافعي أنه يجب أن يعلق باليد منه\n⟦4:288⟧\nشيء، وقوله: (طيبا) أي طاهر والطيب في وصف الأرض ما ليس\nبسبخ، بدلالة قوله: ﴿وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ﴾⟪7:58⟫،\nوقوله: ﴿مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ﴾⟪5:6⟫ منهم من اعتبر ذلك\nفي الدنيا، وقال: ظاهره يقتضي أنه لا يريد أن يتطهروا ويغتسل\nمع الخوف على النفس من الشدة والضنى.\nوقائل ذلك يقتضي بطلان قول من يوجب الغسل من الجنابة مع المرضى، ومنهم من\n⟦4:289⟧\nقال: معنى ذلك لا يعتبروا الجهل والمشقة في هذه العبادات بالحال الظاهرة،\nواعتبروا بالمال فإن ذلك ذريعة إلى تطهير نفوسكم، وما يفضى بكم إلى النعيم\nالمعد لكم، لتعلموا أنه لم يرد حرجا بما أوجبه عليكم، فإنكم إذا اعتبرتم ذلك شكرتم الله على ما طلعكم وعلمتم أن ذلك ليس بحرج ومشقة حملكموها، ونحو ذلك قوله تعالى: ﴿يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ﴾⟪2:185⟫.\nوقوله: ﴿وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ﴾⟪5:6⟫ يعني الطهارة من الذنوب، وقد\nقال عليه الصلاة والسلام: (إذا توضأ العبد فغسل وجهه خرجت ذنوبه من\nوجهه وإذا غسل يده خرجت ذنوبه من يده) وذلك قوله: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا﴾⟪33:33⟫\nوقد حمل على ذلك قوله: ﴿وَثِيَابَكَ فَطَهِّرۡ﴾⟪74:4⟫."}, {"a": [7], "v": 4, "p": 290, "ev": 4, "ep": 291, "sid": 1782, "t": "قوله عز وجل: (واذكروا نعمة الله عليكم وميثاقه الذي واثقكم به إذ قلتم سمعنا وأطعنا واتقوا الله إن الله عليم بذات الصدور (7)\nالميثاق: العهد المستوثق منه وميثاق الله تعالى: المأخوذ من عباده على أضرب: الأول: ما أخذه عليهم بالفطرة: وهو ما ركزه فيهم من المعارف.\nالثاني: ما أخذه عليهم بما أفادهم من العلوم المكتسبة.\nالثالث: ما أخذه عليهم ببعثة الأنبياء وإلزامهم بالشرائع.\nالرابع: ما يلزم بعضهم عن بعض بما يجب عليهم\nالوفاء به، وقد حمل الآية على كل ذلك.\nوقوله: ﴿إِذۡ قُلۡتُمۡ سَمِعۡنَا﴾⟪5:7⟫ تفسير الميثاق الذي أخذه، ووجهه ذكر النعمة. والميثاق بعد أصحاب الطهارة تذكير\n⟦4:291⟧\nللنقمة، وتأكيد لوجوب طاعته. وإن قيل: لما قال: ﴿وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ﴾⟪5:7⟫ ولم يقل نعم الله؟\nقيل: لفظ الواحد في هذا الوضع أبلغ ففيه تنبيه أن في ذكر\nنعمة واحدة شغل عظيم مع أن لفظ الواحد في نحوه يقتضي الجنس.\nوذكر نعمته هو شكرها.\nوقوله: ﴿عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ﴾⟪5:7⟫ أي يقوي الإنسان من\nالعقل والفكر والتخيل الغضب والشهوة.\nوذكر الذات للمبالغة وعلى ذلك قوله تعالى: (ألا إنهم يثنون صدورهم ليستخفوا منه ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون إنه عليم بذات الصدور (5)."}, {"a": [8], "v": 4, "p": 291, "ev": 4, "ep": 294, "sid": 1783, "t": "وقوله عز وجل: (يا أيها الذين آمنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنئان قوم على ألا تعدلوا اعدلوا هو أقرب للتقوى واتقوا الله إن الله خبير بما تعملون (8)\n⟦4:292⟧\n(قوامين لله) أي خلفاءه شهداء بالعدالة، كما قال تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ﴾⟪4:135⟫\nوذلك يقتضي الشهادة لحقوق الناس كما قال الحسن: وعلى قومهم فبما يخالفون أمر الله فيه، كما قال غيره: ولأمر الله أنه حق. كما قال الزجاج. وقيل: معنى الشهادة الحضور أي كونوا في جميع ما يتحرونه مشاهدين لله. كما قال - صلى الله عليه وسلم - (إن لم تكن تراه فإنه يراك)،\nوعدي قوله - صلى الله عليه وسلم - (إن لم تكن تراه فإنه يراك)\n⟦4:293⟧\nوعدي قوله ﴿وَلَا يَجۡرِمَنَّكُمۡ﴾⟪5:8⟫ ب على - حملا على معنى لا يحملنكم.\nوقوله: ﴿عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ﴾⟪5:8⟫ أي على ترك العدالة وذلك قريب من قوله: ﴿وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ﴾⟪5:2⟫\nفالاعتداء قريب من قوله: ﴿أَلَّا تَعۡدِلُواْۚ﴾⟪5:8⟫ لكن قوله: ﴿أَلَّا تَعۡدِلُواْۚ﴾⟪5:8⟫ أبلغ.\nوقوله: (هو) أي العدل فأضمر المصدر لدلالة الفعل عليه كقولهم: -\nمن كذب كان شرا له أي الكذب شرا له،\nإن قيل كيف قال: ﴿أَقۡرَبُ لِلتَّقۡوَىٰۖ﴾⟪5:8⟫، وأفعل إنما يقال في شيئين أشركا في معنى واحد لأحدهما مزية.\nوقد علمنا أن لا شيء من التقوى ومن فعل الخير إلا هو من جملة العدالة.\nفما معنى قوله: ﴿هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ﴾⟪5:8⟫؟\nقيل: إن أفعل وإن كان كما ذكرت، فقد يستعمل على تقدير بناء الكلام على اعتقاد المخاطب في الشيء، لا على ما عليه\nمن حقيقة الشيء في نفسه، قطعا لكلامه وإظهار التبكية، فيقال لمن اعتقد مثلا في\n⟦4:294⟧\nزيد فضلا وإن لم يكن فيه فضل ولكن لا يمكنه أن ينكر أن عمروا\nأفضل منه، فقال أجزم عمروا فهو أفضل من زيد، وعلى ذلك قوله\nتعالى: ﴿ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ﴾⟪27:59⟫ وقد علم أن لا خير فيما يشركون\nبوجه والآية نزلت في يهود احتالوا النبي - صلى الله عليه وسلم -.\nوقيل: في قريش لما صدوا المسلمين. فأمر الله تعالى المسلمين ألا يتركوا معهم مع ذلك استعمال العدالة.\nإن قيل: كيف تصور الظلم وقد أبيح للمسلمين أن\nيقتلوهم ويسبوهم ويسلبوهم وقيل: كل ذلك أبيح لهم على وجه دون\nوجه، متى أخل لمراعاة الحكم المسنون في شيء من ذلك، فهو ظلم\nبل من فعل الإنسان بالكافر مع ما أمر أن يفعل به قصدا إلى\nالتشفي منه تحريا لأمر الله، ففى ذلك تعديا فأوجب الله تعالى تحري العدالة\nمع كل محق، ومبطل وإقامة الشهادة بالحق في كل أمر، وبين الله أنه\nتعالى عالم بما يتحرونه ، ولا يخفى عليه خافية."}, {"a": [9], "v": 4, "p": 294, "ev": 4, "ep": 295, "sid": 1786, "t": "قوله عز وجل: (وعد الله الذين آمنوا وعملوا الصالحات لهم مغفرة وأجر عظيم (9)\nفي قوله: (مغفرة) وجهان: أحدهما: أن يكون في موضع مفعول وعد الله\n⟦4:295⟧\nكقول الشاعر:\nوجدنا الصالحين لهم جزاءا ... وجنات وعينا سلسبيلا\nفجعل قوله: (لهم) جزاء في موضع المفعول به وعطف على\nموضعه قوله: (جنات) بالنصب والثاني أن مفعول وعد محذوف،\nوقوله: ﴿لَهُم مَّغۡفِرَةٞ﴾⟪5:9⟫ تفسير له وعلى كلا التقديرين لا يختلف المعنى."}, {"a": [10], "v": 4, "p": 295, "ev": 4, "ep": 295, "sid": 1787, "t": "قوله تعالى: (والذين كفروا وكذبوا بآياتنا أولئك أصحاب الجحيم (10)\nذلك استئناف كلامهم متضمن للوعيد بتضمن الآية الأولى للوعد."}, {"a": [11], "v": 4, "p": 295, "ev": 4, "ep": 297, "sid": 1787, "t": "قوله عز وجل: (يا أيها الذين آمنوا اذكروا نعمت الله عليكم إذ هم قوم أن يبسطوا إليكم أيديهم فكف أيديهم عنكم واتقوا الله وعلى الله فليتوكل المؤمنون (11)\n⟦4:296⟧\nقيل عنى قوما من اليهود هموا بقتل النبي - صلى الله عليه وسلم -\nوروي: أن يهوديا انتهى إلى النبي - صلى الله عليه وسلم - فسل سيفه\nوقال من يصونك مني، فقال النبى - صلى الله عليه وسلم -: الله، فشام سيفه وأذعن لى).\nوذكر نعمة الله لشكره وقد تقدم ذلك ونبه بقوله تعالى: ﴿وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ﴾⟪5:11⟫ أنه\n⟦4:297⟧\nلا يجوز للمؤمن أن يفزع إلى غير الله في شيء من أموره."}, {"a": [12], "v": 4, "p": 297, "ev": 4, "ep": 299, "sid": 1789, "t": "قوله عز وجل: (ولقد أخذ الله ميثاق بني إسرائيل وبعثنا منهم اثني عشر نقيبا وقال الله إني معكم لئن أقمتم الصلاة وآتيتم الزكاة وآمنتم برسلي وعزرتموهم وأقرضتم الله قرضا حسنا لأكفرن عنكم سيئاتكم ولأدخلنكم جنات تجري من تحتها الأنهار فمن كفر بعد ذلك منكم فقد ضل سواء السبيل (12)\nالنقب كالثقب لكن الثقب يقال لما قضى من الجانب الآخر والنقب، قد يقال له ولغيره وباعتباره قيل: النقبة لأول ما يبدأ من الحرب وقيل لضرب من السراويل نقبة، وكلب نقيب مثقوب الحنجرة لئلا يرفع صوته.\nوالمناقب ما ينقب عنه من المفاخر والنقيب\nكالعريف يقال نقب وعرف وهو الذي عنى أحوال الجيش.\nقال أبو عبيدة: هو الضامن على القوم.\nقال قتادة: هو الشاهد،\nوقيل: هو فعيل في معنى مفعول وهو المختار، وذلك إشارة إلى\n⟦4:298⟧\nما قال: ﴿وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ﴾⟪44:32⟫.\nوالمذكور في قوله: ﴿وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا﴾⟪7:160⟫\nوأصل التعزير النصرة إما بأن لا يظلم أولا يظلم.\nكما قال عليه الصلاة والسلام: (أنصر أخاك ظالما أو مظلوما، فقال بعضهم: - أنصره مظلوما فكيف أنصره ظالما؟\nفقال: تمنعه من الظلم).\nوتعزير السلطان عى بذلك كما سمي التأديب، وإقراض الله عبارة\nعن كل إنفاق محمود أوجبه أو ندب إليه، وسمي ذلك قرضا تلطفا بعباده وأن\n⟦4:299⟧\nما يطلبه منهم مع كونه في الحقيقة ملكا له تعالى، يأخذه ليرد عوضه خيرا\nمنه، وعلى ذلك: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا﴾\nوالقرض: اسم للمقرض كالعطاء في كونه اسم للمعطى.\nوقيل: هو موضوع موضع الإقراض، كقوله تعالى: ﴿وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا﴾⟪71:17⟫\n﴿وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ﴾⟪5:12⟫ أي ضمن نصرتكم.\nوقوله: ﴿وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ﴾⟪5:12⟫ يتصل به قوله: ﴿لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ﴾⟪5:12⟫.\nوقوله: ﴿وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ﴾⟪5:12⟫.\nجملتان فصل بهما بين الكلامين المتصلين على سبيل الاعتراض المؤكد للكلام،\nوقال: ﴿لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ﴾⟪5:12⟫ أي إن أديتم الفرائض ونصرتم الرسل\nوأنفقتم في سبيل المكارم، تجوفي عن ذنوبكم ومكنتم من الجنة، ومن كفر بعد أخذ الميثاق فقد ضل عن الصراط المستقيم."}, {"a": [13], "v": 4, "p": 299, "ev": 4, "ep": 302, "sid": 1791, "t": "قوله عز وجل: (فبما نقضهم ميثاقهم لعناهم وجعلنا قلوبهم قاسية يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع على خائنة منهم إلا قليلا منهم فاعف عنهم واصفح إن الله يحب المحسنين (13)\n⟦4:300⟧\nقد تقدم ذكر نقض الميثاق وقلوبهم قاسية هي كقوله: ﴿فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ﴾⟪2:74⟫. وقرأ قسية وقيل هي فعيله منه، وقيل: معناه ليست بخالصة الإيمان من قولهم درهم قسي إذا خالطه غشية الخائنة.\nقيل: مصدر كالخيانة، نحو عوفي عافية (والمؤتفكات بالخاطئة)، و (أهلكوا بالطاغية).\nوقائله: بمعنى قيلولة. وقيل معناه: تطلع على جماعة خائنة، وقيل: على رجل خاص كقوله راوية وداعية ونابغة قال الشاعر:\n⟦4:301⟧\nحدثتك نفسك بالوفاء ولم تكن ... للغدرخائنة مغل الأصبع\nإن قيل لما قال: ﴿وَنَسُواْ حَظّٗا﴾⟪5:13⟫ فنكر؟\nقيل للإنسان حظان : حظ دنيوي، وحظ أخروي، فأشار بقوله (حظا) إلى الأخروي.\nونبه بقوله: ﴿مِّمَّا ذُكِّرُواْ بِهِۦۚ﴾⟪5:13⟫ على أن الله قد ذكرهم ذلك بما وضع فيهم من العقل وبما أنزل عليهم من الكتب فنسوه أي تركوه، واستعارة لفظ النسيان لتركهم إياه مبالغة في ذمهم وتمام القصة عند قوله: ﴿وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ﴾⟪5:13⟫ ثم استأنف على سبيل الذم لهم ﴿وَلَا تَزَالُ تَطَّلِعُ﴾⟪5:13⟫\nوقوله: ﴿فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ﴾⟪5:13⟫ أمر بالعفو عما يضمرونه،\nوقيل: أمر بالعفو عمن دخل في العهد.\nوقال قتادة: ذلك منسوخ بقوله: ﴿قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾⟪9:29⟫.\n⟦4:302⟧\nوقال غيره: بل بقوله: ﴿وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ﴾⟪8:58⟫. والوجه أن يكون أمر بالعفو عن المستبطن وعمن دخل في العهد فلا تكون منسوخة."}, {"a": [14], "v": 4, "p": 302, "ev": 4, "ep": 303, "sid": 1794, "t": "قوله عز وجل: (ومن الذين قالوا إنا نصارى أخذنا ميثاقهم فنسوا حظا مما ذكروا به فأغرينا بينهم العداوة والبغضاء إلى يوم القيامة وسوف ينبئهم الله بما كانوا يصنعون (14)\nذم النصارى بنقض الميثاق، كما ذم اليهود وجعل عقوبتهم إيقاع العداوة والبغضاء بينهم، وأصل الغرا: من أغرا به أي لصق، وكيفية إيقاع الله الجداوة بينهم على ما تقدم من\n⟦4:303⟧\nنسبته تعالى نحو ذلك الفعل إلى نفسه."}, {"a": [15, 16], "v": 4, "p": 303, "ev": 4, "ep": 304, "sid": 1795, "t": "قوله عز وجل: (يا أهل الكتاب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتاب ويعفو عن كثير قد جاءكم من الله نور وكتاب مبين (15) يهدي به الله من اتبع رضوانه سبل السلام ويخرجهم من الظلمات إلى النور بإذنه ويهديهم إلى صراط مستقيم (16)\nأعاد بما يخفون من الكتاب إلى مثل إخفاء بنبوة النبي - صلى الله عليه وسلم -، وحكم رجم الزاني، وأخذهم الرشى،\nوقوله ﴿وَيَعۡفُواْ عَن كَثِيرٖۚ﴾⟪5:15⟫ أي يتجافى من إظهار كثير مما يخفونه، وبين في\nهذه الآية النعم الثلاث التي خص بها العباد وهي: - النبوة والعقل والكتاب.\nوذكر في الآية التانية ثلاث أحكام، يرجع كل واحد إلى نعمه مما تقدم.\nفقوله: ﴿يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ﴾⟪5:16⟫ راجع إلى\n⟦4:304⟧\nقوله: ﴿قَدۡ جَآءَكُمۡ رَسُولُنَا﴾⟪5:15⟫ أي بهذا البيان إلى طريق السلامة من\nالتبعة ممن تحرى مرضاة الله.\nقوله تعالى: ﴿وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ﴾⟪5:16⟫ راجع إلى قوله: ﴿قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ﴾⟪5:15⟫.\nوقوله: ﴿وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ﴾⟪5:16⟫ راجع إلى قوله: ﴿وَكِتَٰبٞ مُّبِينٞ﴾⟪5:15⟫. كقوله: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫.\nوالسلام قيل هو: اسم الله تعالى نحو قوله: ﴿ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ﴾⟪59:23⟫.\nوقيل: هو السلامة نحو الخسار والخسارة\nوالضلال والضلالة.\nسبل السلام هي المشار إليها بقوله: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ﴾⟪16:125⟫."}, {"a": [17], "v": 4, "p": 304, "ev": 4, "ep": 306, "sid": 1796, "t": "قوله عز وجل: (لقد كفر الذين قالوا إن الله هو المسيح ابن مريم قل فمن يملك من الله شيئا إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعا ولله ملك السماوات والأرض وما بينهما يخلق ما يشاء والله على كل شيء قدير (17)\nوإن قيل: إن أحدا لم يقل الله هو المسيح، وإن قالوا:\n⟦4:305⟧\nالمسيح هو الله، وذلك أن عندهم أن المسيح من لاهوت وناسوت، فيقولون\nيصح أن يقال: المسيح هو اللاهوت وهو ناسوت، كما يصح أن يقال: الإنسان هو حيوان وهو نبات لما كان مركبا منهما.\nقالوا ولا يصح أن يقال اللاهوت هو المسيح، كما لا يصح أن يقال الحيوان هو الإنسان.\nقيل: إنهم قالوا هو المسيح على وجه آخر غير ما ذكرت،\nوهو ما روي عن عمد بن كعب القرظي: أنه\nلما رفع عيسى عليه الصلاة السلام اجتمع طائفة من علماء بني إسرائيل فقالوا\nما تقولون في عيسى فقال أحدهم: أتعلمون أحدا يحيي الموتى إلا الله فقالوا\nلا، فقال: أتعلمون أن أحدا يعلم الغيب إلا الله فقالوا: لا.\nفقال: أتعلمون أن أحدا يبرئ الأكمه والأبرص إلا الله، قالوا: لا.\nقال: فما الله إلا من هذا وصفه أي حقيقة الإلهية فيه.\nوهذا كذلك. الكريم زيد أي حقيقة الكرم في زيد، وعلى هذا قالوا: إن الله هو المسيح ابن مريم.\nإن قيل: (فا) في قوله: ﴿قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا﴾⟪5:17⟫\n⟦4:306⟧\nمما يقتضي تكذيبهم فيما ادعوه قيل:\nذكر تعالى بذلك شيئين اقتضيا تكذيبهم. وذلك أنهم مقرون أن الله تعالى هو\nسبب وجود عيسى وأمه. وأنه تعالى غاية الموجودات وسببها ومالكها ولا شيء هو سبب لوجود الله تعالى وأنه أهو مالك قادر على إهلاك كل ذلك، فنبه تعالى بقوله: ﴿فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا﴾⟪5:17⟫ أنه لو ارتفع كل ذلك لصح\nمع بقائه ولو توهم هو تعالى مرتفعا لما صح وجودهم، وهذا أوضح دلالة أن\nلا يصح فادعوه في عيسى ثم.\n﴿وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾⟪5:17⟫ تنبيها أن الإنسان يحتاج إلى الابن ليتقوى به أيام حياته ويخلفه بعد وفاته، والله تعالى غني\nعن ذلك إذ هو مالك السموات والأرض وما بينهما وموجودها.\nوقوله تعالى: ﴿لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ﴾⟪5:17⟫ أي اعتقدوا اعتقادا باطلا عن ظن كاذب\nلأن هذا هو حقيقة الكفر وقيل معناه جحدوا نعمة الله وهذا على اعتبار معنى\nالكفر في الأصل."}, {"a": [18], "v": 4, "p": 307, "ev": 4, "ep": 309, "sid": 1799, "t": "قوله عز وجل: (وقالت اليهود والنصارى نحن أبناء الله وأحباؤه قل فلم يعذبكم بذنوبكم بل أنتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السماوات والأرض وما بينهما وإليه المصير (18)\nادعى كل واحد من اليهود والنصارى أنهم أبناء الله وأحباؤه وقد روي أنهم قالوا ذلك قولا حذرهم النبي عليه الصلاة والسلام نقمة الله، فقالوا: لا تخوفنا فإنا أبناء الله وأحباؤه وزعم اليهود أن الله تعالى أوحى إلى إسرائيل أن ولدك بكري من الولد، وأما النصارى فقد قيل إنهم قالوا ذلك لما حكي عن قول المسيح أنا ذاهب إلى أبي وأبيكم، وروي أنهم قالوا: ما اقتضى معناه هذا القول وإن لم يتفوهوا بذلك تفوها كقولك: فيمن يدعي تخصصا بسلطان فلان يقول أنا يد السلطان ولسانه، قيل:\nوكانوا يقولون إن غضب الله علينا كما يغضب الإنسان على ابنه وحبيبه.\nفكذبهم الله فيما ادعوه من محبتهم له ومحبته لهم، فإن المحبة تقتضي ترك المخالفة ومن أحب الله لم يخالفه، ولهذا قال الشاعر:\n⟦4:308⟧\nتعصي الإله وأنت تظهر حبه ... هذا محال فى القياس بديع\nلوكان حبك صادقا لأطعته ... إن المحب لمن أحب مطيع\nولو أنه يحبهم لما عذبهم.\nفقد روي أنه إذا أحب الله عبدا تعهده وأحسن إليه . روي عنه عليه الصلاة والسلام: (إن الله قال ما زال العبد يتقرب إلي بالنوافل حتى أحبه فإذا أحببته كنت سمعه الذي يسمع به وبصره الذي يبصر به).\nإن قيل: كيف احتج عليهم بهذا ولم يقولوا إنا لا نعذب بل قالوا: إنا لا نعذب إلا أياما بقدر ما عبدنا فيه العجل؟\nقيل: إنه إشارة إلى ما تقدم من تعذيب الله إياهم، فكأنه قيل: فلم عذب من كان قبلكم الذين كانوا أمثالكم ثم قال: ﴿بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ﴾⟪5:18⟫ أي نسبتكم إليه نسبة العبودية كسائر الناس وإنما يفضل من يفضل بالتقوى، كما قال: ﴿إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ﴾⟪49:13⟫.\n⟦4:309⟧\nوكرر مع هذه الآية قوله: ﴿وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾⟪5:18⟫ توكيدا لكونهم ملكا له، ونبه بقوله: ﴿وَإِلَيۡهِ ٱلۡمَصِيرُ﴾⟪5:18⟫ على معنى قوله: ﴿ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ﴾ ونحوه من الآيات."}, {"a": [19], "v": 4, "p": 309, "ev": 4, "ep": 310, "sid": 1801, "t": "قوله عز وجل: (يا أهل الكتاب قد جاءكم رسولنا يبين لكم على فترة من الرسل أن تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله على كل شيء قدير (19)\nقوله: ﴿أَن تَقُولُواْ﴾⟪5:19⟫ أي كيلا تقولوا بين الله لكم أن\nتضلوا.\nوالفترة السكون والبطوء يقال فتر الشيء فتورا.\n⟦4:310⟧\nوقد تقدم أن بعثة الأنبياء من ضرورات العباد الى لا يستغني\nعنها فعامة الناس يجهلون جزئيات مصالحهم وكلياتهم، وخاصتهم\nيعرفون كلياتها دون جزئياتها، ولا يمكنهم أن يفرقوا الكليات.\nعلى التحقيق إلا بعد انقضاء كثير من\nعمرهم، فسهل الله السبيل على جماعتهم من هدايتهم\nإلى مصالحهم وعلى ذلك قوله:\n﴿وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ﴾⟪28:59⟫\nفبين أنه تعالى أزاح علتهم فيمن بعث إليهم من البشير والنذير"}, {"a": [20], "v": 4, "p": 310, "ev": 4, "ep": 313, "sid": 1802, "t": "قوله تعالى: (وإذ قال موسى لقومه يا قوم اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء وجعلكم ملوكا وآتاكم ما لم يؤت أحدا من العالمين (20)\nقيل: ملوكا أي أحرزوا من رزق المطامع الدنيوية،\nوروي عن ابن عباس أنه قال: من كان له\n⟦4:311⟧\nزوجة وخادم ودار فهو ملك.\nوقيل: من له ما يستغني به عن تكلف\nالأعمال فهو ملك. وقيل: جعلهم ملوكا من حيث ملكوا أنفسهم\nبالتخلص من القبط بعد أن استعبدوهم.\nوقيل عنى بقوله: (ملوكا) أي جعلكم بالقوة التي آتاكم مستصلحين لذلك، فإن من له المعرفة بالسياسات الثلاث سياسة لنفسه وسياسة لداره وسياسة لضعفه فهو ملك وإن لم يتولى سياسة غيره.\nفجعل النبوة فيهم خاصا وجعل\nالملوكية فيهم عاما للمعنى الذي ذكرنا، وقوله: ﴿وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ﴾⟪5:20⟫ ممن تقدمهم، وإنما قال ذلك بالإضافة إلى\nالأديان فإن الله خلق الإنسان وجعل لهم دينا ينشأ حالا فحالا، فكل يوم\nهو في كمال، فدين موسى - عليه السلام - كان أكمل من دين من قبله، ودين عيسى - عليه السلام - أكمل من دين موسى، ودين محمد - صلى الله عليه وسلم - أكمل الأديان إذ كان به كمل كما\n⟦4:312⟧\nقال تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫\nوقيل: أراد آتاكم ما لم يؤت أحدا من العالمين مما عدا الإنسان،\nفإن قيل: هذا لا يصح لأمرين أحدهما: أن يسقط تخصيص بني إسرائيل، والثاني: أنه لا يقال: لما عدا جنس العقلاء أحد قيل أما كون هذه النعمة على غير بني إسرائيل فليس يقتضي أن لا يخصصوا بالخطاب، فقد يقال لكل واحد ممن يتنبه على نعمة الله عليه أليس قد من الله عليك بأن أعطاك يدا تبطش به، ولسانا تتكلم به، وليس يقتضي مشاركة غيره في هذه النعمة أن\nلا يكون للمخاطب فائدة، وأما قولنا: وإن كان يختص به جنس العقلاء\nفقد يقال ذلك لغيره إذا حمع بينه وبين جنس العقلاء كلفظة من في قوله\n⟦4:313⟧\n﴿وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ﴾⟪24:45⟫ فأطلق من على البهائم\nلما كان تفضيلا لجملة منها العقلاء."}, {"a": [21, 22], "v": 4, "p": 313, "ev": 4, "ep": 315, "sid": 1805, "t": "قوله عز وجل: (يا قوم ادخلوا الأرض المقدسة التي كتب الله لكم ولا ترتدوا على أدباركم فتنقلبوا خاسرين (21) قالوا يا موسى إن فيها قوما جبارين وإنا لن ندخلها حتى يخرجوا منها فإن يخرجوا منها فإنا داخلون (22)\nالأرض المقدسة: بيت المقدس، وقيل: دمشق، وفلسطين، وبعض الأردن. وقال مجاهد: هي أرض الطور. وقال قتادة: هى الشام.\n⟦4:314⟧\nإن قيل كيف قال: ﴿كَتَبَ ٱللَّهُ لَكُمۡ﴾⟪5:21⟫ ثم قال: ﴿فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ﴾⟪5:26⟫\nقيل: قال بعضهم: وهب الله ذلك لهم ثم حرمها عليهم لما تلقوا نعمته\nبالرد والكفران.\nوقيل: كتب لهم أنهم إن دخلوها فهي لهم.\nوقيل: معنى ﴿كَتَبَ ٱللَّهُ لَكُمۡ﴾⟪5:21⟫ أي أوجبها عليكم.\nإن قيل: فقد كان يجب أن يقول كتب الله عليكم على هذا؟\nقيل: إنما ذكر لكم معنى لطيف وهو أنه نبه أنه أوجب عليهم وجوبا يستحقون به ثوابا يحصل لهم.\nوذلك كقولك لمن يرى تأذيا بشيء أوجب فيقال: هذا لك لا عليك، تنبيها\nعلى الغاية التي هي الثواب. وإذا قيل كتب عليه فليس اللفظ يقتضي\nعلى الغاية التي هي الثواب بل يقتضي مجرد الإيجاب فذكر أنهم امتنعوا من\nدخولها لكون قوم جبارين فيها، واشترطوا أن لا يدخلوها إلا أن يخلوا\nلهم.\nوقولهم ﴿وَإِنَّا لَن نَّدۡخُلَهَا﴾⟪5:22⟫ فقد قال بعضهم: إن ذلك ليس\n⟦4:315⟧\nبعصيان منهم بل بإظهار العجز عن دخولها، وروي أن هؤلاء\nالجبارين كانوا قوما لهم بسطة في الجسم حتى أن رجلين من النقباء ذهبا\nيتجسسان فرآهما رجل منهم في بستانه فجعلهما في الكم من الفواكه\nونثرهما بين يدي ملكهم فقال: أنتم تريدون قتالنا، ارجعا إلى قومكم\nفأخبراهم بخبرنا.\nوقال بعض الناس: الأرض المقدسة، عبارة عن الدين\nالحق الذي رشحه الله لهم فامتنعوا من تحريه تفاديا من قوم كانوا على\nذلك الدين، كانوا يستحقرون. وهذا بعيد على ما يقتضيه رد\nالكلام."}, {"a": [23], "v": 4, "p": 315, "ev": 4, "ep": 316, "sid": 1807, "t": "قوله عز وجل: (قال رجلان من الذين يخافون أنعم الله عليهما ادخلوا عليهم الباب فإذا دخلتموه فإنكم غالبون وعلى الله فتوكلوا إن كنتم مؤمنين (23)\n⟦4:316⟧\nقال قتادة: يعني رجلين من الذين يخافون أنعم الله عليهما ادخلوا عليهم.\nوقيل: من الذين كانوا يخافون من الجبارين فأنعم الله عليهما بالإسلام\nفأمنهما، وقيل: كان يوشع بن نون وكالوب بن يوقنا وكانا من\nالنقباء. وبينا أن الله تعالى ينزل النصرة بقدر الجهد، وأنكم إذا\nبذلتم من أنفسكم الاجتهاد في الدخول عليهم الباب وجدتم من الله\nالنصرة، ويجعل الغلبة لكم وأمراهم بالتوكل، فكأنه قال: إن كنتم\nمتوكلين على الله يكفكم على ما قال تعالى: ﴿وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ﴾⟪65:3⟫."}, {"a": [24], "v": 4, "p": 317, "ev": 4, "ep": 317, "sid": 1809, "t": "قوله عز وجل: (قالوا يا موسى إنا لن ندخلها أبدا ما داموا فيها فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون (24)\nذكر جهلهم وقلة معرفتهم بالله، وأنهم ما قدروا الله حق قدره حيث أمروه أن يستصحبه إلى الجواب استصحاب الأشخاص وبكتهم بامتناعهم من الدخول إما جبنا وإما قصدا إلى العصيان، وأيهما كان فمذموم.\nإن قيل: ما فائدة الجمع بين قوله: (أبدا) وقوله: ﴿مَّا دَامُواْ فِيهَا﴾⟪5:24⟫؟\nقيل: إن امتناعهم من دخولها لكون هؤلاء فيها، وإن اعتبار ذلك ليس في وقت دون وقت بل كل وقت، ما يدخلونها من كونهم فيها وروي أن المقداد قال للنبي - صلى الله عليه وسلم -: (أما والله ما نقول لك ما قال بنو إسرائيل لموسى اذهب أنت وربك فقاتلا إنا هاهنا قاعدون، ولكن نقتل حيث شئت)."}, {"a": [25], "v": 4, "p": 318, "ev": 4, "ep": 320, "sid": 1810, "t": "قوله عز وجل: (قال رب إني لا أملك إلا نفسي وأخي فافرق بيننا وبين القوم الفاسقين (25)\nأظهر موسى شر ما به وبين عذره في غيره وأن ذلك لقلة انقيادهم له.\nإن قيل: كيف يصح أن يقول لا أملك إلا نفسي، والإنسان في الحقيقة لا يملك نفسه وأخاه، إذا الملك هو التصرف في الشيء بالبيع والشراء؟\nقيل: هذا سؤال من هو بعيد عن متصرفات كلامهم، بل عن معرفة\nحقائق الأشياء، فإن الإنسان إذا انقاد له قواه فيما يسومها من فعل\nالخير، يقال: هو مالك لنفسه وإذا امتنعت عليه قواه، يقال: هو غير\nمالك لها، وليس تصرف الملك والمالك على وجه واحد.\nوإعراب قوله: (وأخى) محتمل له أربعة أوجه: الأول الرفع عطف على\n⟦4:319⟧\nموضع (إني).\nالثاني: على الضمير في أملك،\nالثالث: نصب على المضمر في (إني)،\nالرابع: نصب على قوله: (نفسى).\nوقوله: ﴿فَٱفۡرُقۡ بَيۡنَنَا﴾⟪5:25⟫ أي بين مسكننا في الدنيا.\nوقيل: بين منزلينا في الآخرة، ولم يقل بيننا وبينهم\nبل قال: ﴿وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ﴾⟪5:25⟫ ليكون دعاؤه أبلغ\nوأقرب إلى استعمال الأدب في مخاطبة الله تعالى، ولأنه من يجوز\nأن يصلح منهم بعضهم، فيجب أن لا يعين، بل يذكر\nالوصف الذي هوالفسق فيتعلق به الحكم، وذكر\nالفسق دون الكفر إذ\n⟦4:320⟧\nهو أعم منه."}, {"a": [26], "v": 4, "p": 320, "ev": 4, "ep": 322, "sid": 1812, "t": "قوله عز وجل: (قال فإنها محرمة عليهم أربعين سنة يتيهون في الأرض فلا تأس على القوم الفاسقين (26)\nقال الربيع: حرم عليهم أربعين سنة، وقال الحسن وقتادة: بل\nحرم عليهم على التأبيد، وإنما كانوا يتيهون أربعين سنة.\nفقوله: ﴿أَرۡبَعِينَ سَنَةٗۛ﴾⟪5:26⟫ يتعلق بقوله: (يتيهون) على هذا،\nوتحريم ذلك عليهم قيل: إنه كان\n⟦4:321⟧\nتحريم تعبد فإنهم أمروا أن لا يدخلوها.\nوقيل: منعوا منها من جهة إضلالهم عنها فإنهم كانوا إذا أمسوا ردهم الله بقوة إلهية إلى حيث ما ارتحلوا عنه فقوله: ﴿مُحَرَّمَةٌ عَلَيۡهِمۡۛ﴾⟪5:26⟫ كقوله: ﴿وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ﴾⟪28:12⟫ وأنهم ما خرجوا من التيه حتى مات هؤلاء\nوانتقل أمرهم إلى أبنائهم.\nوروي أن قدر الأرض التي تاهوا فيها ستة فراسخ.\nوقد قيل: لم يكن موسى وهارون معهم في التيه، لأن ذلك\n⟦4:322⟧\nكان عذابا عليهم دونهما.\nومن لفظ التيه اشتق تاه فلان وتوهه.\n﴿فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ﴾⟪5:26⟫ قيل: هو خطاب للنبي - صلى الله عليه وسلم - خاصة تسلية له بأن المخالفة على الأنبياء عادة الفسقة في\nكل زمان.\nوقيل: بل هو من حملة ما خوطب به موسى وإن كان فيه\nتسلية للنبي - صلى الله عليه وسلم -."}, {"a": [27], "v": 4, "p": 322, "ev": 4, "ep": 325, "sid": 1814, "t": "قوله عز وجل: (واتل عليهم نبأ ابني آدم بالحق إذ قربا قربانا فتقبل من أحدهما ولم يتقبل من الآخر قال لأقتلنك قال إنما يتقبل الله من المتقين (27)\nالقربان اختص في المتعارف، بالذبيحة المتقرب بها.\nوإن كان في الأصل عاما في كل ما يتقرب، فهو فعلان كالعدوان\n⟦4:323⟧\nوالشكران والكفران.\nقيل: ابنا آدم كانا هابيل وقابيل، وكانا من قصتهما أن حواء ولدت مع كل واحد منهما بنتا فالتي ولدت مع قابيل سميت إقليميا والتي مع هابيل لبوخ، ثم إن حواء قالت ليتزوج كل واحد منكما أخته المولودة مع أخيه وكانت إقليميا أحسن من لبوخ فقال هابيل سمعت وأطعت، وقال قابيل لا أرضى بل أريد إقليميا التي ولدت معي، وكان غرضه جمالها، فلما اختلفا قال لهما ليقرب كل واحد منكما قربان فمن قبل الله قربانه يتزوج إقليميا، وكان هابيل صاحب غنم وعهد إلى كبش أنتج فذبحه، وكان قابيل صاحب زرع وعهد إلى سيء من الفوم رديء فقربه فنزلت نار من السماء وأخذت الكبش وكان ذلك علامة قبول القربان.\nورد في الخبر: أن هذا الكبش حصنه الله في الجنة إلى أن فدي به ذبيح إبراهيم عليه الصلاة والسلام.\nوقيل: رعى في الجنة ثمانين خريفا. وقيل: أربعين،\nوقيل إن ذلك في\n⟦4:324⟧\nرجلين من بني إسرائيل يقال لهما ابنا آدم فإن إحلال الله للقرابين في\nزمن إسرائيل، واستدل هذا القائل بقوله: ﴿ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ﴾⟪3:183⟫، والأول أصح، فقد روى مسروق عن عبد الله، عن النبي عليه الصلاة والسلام: (لا تقتل نفس ظلما إلا كان على ابن آدم كفل من دمها).\nوالذي لم يقبل منه القربان إما لكونه، على\n⟦4:325⟧\nغير الوجه الذي كان يجب أن يكون عليه ما لكون صاحبه مقصرا في\nسائر عباداته ولما قال أخوه حسدا (لأقتلنك) قال:\n﴿إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ﴾⟪5:27⟫ حثا له على التقوى، أي لا تقتلني فإنه إنما\nلم يقبل منك لأنك لست بمتق، والله يتقبل من المتقين.\nوفي الآية تعظيم أمر الحسد، وأنه يحمل الإنسان على أعظم الكبائر، وقد قيل: أثاني الشرور ثالثه الحرص والكبر والحسد فآدم (أولى) من الحرص وإبليس من الكبر وقابيل من الحسد."}, {"a": [28], "v": 4, "p": 325, "ev": 4, "ep": 326, "sid": 1817, "t": "قوله عز وجل: (لئن بسطت إلي يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك إني أخاف الله رب العالمين (28)\nقال ابن عباس: يعني إن بدأتني بالقتل لم أبدأ بقتلك، ولم يعن أني لا أمنعك عني، فمنع الإنسان القائل عن نفسه بقدر وسعه واجب.\nوقيل: إن من تعرض لقتله فله أن يدفع عن\n⟦4:326⟧\nنفسه وله أن يستسلم. وعن أيوب قال: أول من أخذ بهذه الآية في\nهذه الأمة عثمان، وقيل: قد كان حينئذ يجب أن لا يدفع أحد عن\nنفسه، كما روي أن عيسى عليه الصلاة والسلام قال لأصحابه: (من\nلطم من ناحية يمينه فليمكن من ناحية شماله)، وذلك عن الحسن\nومجاهد."}, {"a": [29], "v": 4, "p": 326, "ev": 4, "ep": 327, "sid": 1818, "t": "قوله عز وجل: (إني أريد أن تبوء بإثمي وإثمك فتكون من أصحاب النار وذلك جزاء الظالمين (29)\nأي بإثم قتلي وإثمك الذي كان منك فلم يتقبل لأجله قربانك.\nإن قيل كيف جاز أن يريد لغيره أن يفعل الشر، وأن يكون\nمن أصحاب النار؟\nقيل: أراد ذلك بشرط القتل أي أريد إن قتلتني أن تبوء بإثمي وإثمك وأن\nتكون من أصحاب النار، وهذه الإرادة ليست بقبيحه.\n⟦4:327⟧\nوالبواء الرجوع، والمباء المنزل الذي ينزل فيه الإنسان، وهم في هذا الأمر\nبوأ أي سواء يرجع إليه كل واحد مثل رجوع الآخر ومنه فلان بوأ فلان\nفي القود."}, {"a": [30], "v": 4, "p": 327, "ev": 4, "ep": 328, "sid": 1819, "t": "قوله عز وجل: (فطوعت له نفسه قتل أخيه فقتله فأصبح من الخاسرين (30)\nقوله ﴿فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ﴾⟪5:30⟫ كقولهم أسمحت قرينته وانقادت نفسه، وسولت، يقال: طاعت نفسه، وطوعت وتطوعت، والنفس توصف تارة بأنها طوعت\nفيما أمرت من الشر كهذه الآية، وتارة بأنها أمرت بالشر كقوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫، ونبه بقوله: (فقتله) أنه تبع\n⟦4:328⟧\nشيطانه الداعي إلى ذلك تنبيها أن متابعة الشيطان والهوى سبب كل شر\nولهذا قال: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ﴾⟪38:26⟫،\nوقال: ﴿أَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾.\nوقوله: ﴿فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ﴾⟪5:30⟫ إشارة إلى نحو قوله: ﴿خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ﴾.\nقال ابن عباس: أما في الدنيا فأسخط والديه وبقي بلا أخ،\nوأما في الآخرة فأسخط ربه تعالى، وأمر به إلى النار.\nقال قوله: (ربنا أرنا اللذين أضلانا من الجن والإنس).\nقال يريهم من الإنس قابيل ومن الجن إبليس، فقد روى:\nأنه لم يكن يدري قابيل كيف يقتل أخاه فأخذ يطعن رأسه فجاء إبليس\nفقال خذ هذه الصخرة فأشدخه بها."}, {"a": [31], "v": 4, "p": 328, "ev": 4, "ep": 329, "sid": 1820, "t": "قوله تعالى: (فبعث الله غرابا يبحث في الأرض ليريه كيف يواري سوءة أخيه قال يا ويلتى أعجزت أن أكون مثل هذا الغراب فأواري سوءة أخي فأصبح من النادمين (31)\n⟦4:329⟧\nقال ابن عباس: لما قتل أخاه تحير لم يدر كيف يفعل به فقيض الله تعالى\nغرابين تقاتلا فقتل أحدهما الآخر فدفنه، فتنبه قابيل لدفن أخيه،\nووجه ذلك أنه ما من صنعة يتعاطاها الإنسان بالتعلم إلا وقد سخر الله لمثل ذلك الصنعة حيوانا يتعاطاه، وجعل الله تعالى ذلك سببا لتعلم الناس ذلك منه، فمن الحيوان ما يسبح ومنها ما يمشي ومن عادة الغراب دفن الأشياء فلما رأى قابيل ذلك تنبه لما يجب أن يفعل فاستصغر نفسه لقصوره عن معرفة\nما اهتدى إليه الغراب، فأخذ يتحسر، ويتولول وندم ندما لا يثنيه\nولا يحد به كما قال الشاعر: -\n..............\nوما يغني من الحدثان ليت\nوليست هذه الندامة بندامة التوبة."}, {"a": [32, 33, 34], "v": 4, "p": 330, "ev": 4, "ep": 338, "sid": 1822, "t": "قوله عز وجل: (من أجل ذلك كتبنا على بني إسرائيل أنه من قتل نفسا بغير نفس أو فساد في الأرض فكأنما قتل الناس جميعا ومن أحياها فكأنما أحيا الناس جميعا ولقد جاءتهم رسلنا بالبينات ثم إن كثيرا منهم بعد ذلك في الأرض لمسرفون (32)\nالأجل: قطع الماء والآجل وقت مقطوع يقطع من وقته، والآجل نقيض العاجل وهو الذي جعل له أجل ما، والأجل قطيع من الغنم، وذلك لقولهم الصرمة والقطعية والفرقة ونحوها مما اشتق من الأسماء المتضمنة لمعنى القطع. وأجل فلان على فلان جنى عليهم جناية. أجله حضر.\nقوله: ﴿مِنۡ أَجۡلِ ذَٰلِكَ﴾⟪5:32⟫ أي من جناية ذلك، وقيل: من سبب ذلك كقولهم من أجله وبين بقوله: ﴿مِنۡ أَجۡلِ ذَٰلِكَ﴾⟪5:32⟫ أنه كان من أول من سن القتل.\nوعنده شرع هذا الحكم، وذلك كقولك من أجل ماعز شرع النبي - صلى الله عليه وسلم - حكم الرجم، أي عنده شرع، وإنما خص بني إسرائيل\nدون غيرهم لأن كتابهم أول كتاب بين فيه فيه الأحكام.\n⟦4:331⟧\nوقيل: لأنه كثر منهم القتل، وبين أن الساعي في قتل نفس لم يلزمها قتل\nما يقتضي الاقتصاص أو فساد وذلك إلى نحو ما قال عليه الصلاة والسلام: (كفر بعد إسلام، وزنا بعد إحصان).\nوقوله: ﴿فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا﴾⟪5:32⟫\n⟦4:332⟧\nفإن الناس لما كانوا كجسم واحد ونسبة آحادهم إليه كنسبة\nأعضاء الجسم الواحد إليه، صار الساعي في إهلاك بعض الجسم كالساعي في\nإهلاكهم، كما أن الساعي في إهلاك بعض الجسم كالساعى في إهلاك\nكله، صار قتل الواحد كقتل الناس، ولهذا جاء في التفسير أن المؤمنين\nخصم للقاتل ولهذا قال: ﴿وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ﴾⟪4:93⟫، وقال مجاهد: فلو قتل الناس جميعا لم يرد\nفي جزاءه على جزاء قوله: ﴿وَمَنۡ أَحۡيَاهَا﴾⟪5:32⟫ أي من نجاها من الهلاك إما\nبالحماية عليها، وإما بالعفو عنها إذا لزمها قصاص يستحب منه العفو.\nقال مجاهد: (من أحياها) أي من ترك قتلها.\nقال الحسن: ﴿مَن قَتَلَ نَفۡسَۢا﴾⟪5:32⟫ أي من أضله عن طريق الهدى،\n(ومن أحياها) أي دعا مشركا إلى الإيمان فهداه وأرشده\n⟦4:333⟧\nفكأنما أحيا آدم عليه الصلاة والسلام وولده إلى القيامة.\nقوله عز وجل: ﴿وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ﴾⟪5:32⟫. تنبيه أن الله لم يخلهم من بشير ونذير على عبادته في الأمم.\nوالإسراف: الإبعاد في الخروج عن الحق، وعن الاستقامة التي هي\nالعدالة في كل شيء هذا أصله، وإن تعورف في الخروج عن العدالة في إنفاق\nالمال، وقد وصف قوم لوط بالإسراف لخروجهم عما أبيح لهم إلى ما حظر عليهم، فبين تعالى أن كثيرا منهم بعد مجيء رسلهم بالبينات يخلون بالعدالة وما شرع\n⟦4:334⟧\nلهم وأبعدوا في التعدي.\n(إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأرض ذلك لهم خزي في الدنيا ولهم في الآخرة عذاب عظيم (33)\nمحاربة الله ورسوله: هو السعي في الأرض بالفساد، وسمي ذلك محاربة الله ومحاربة رسوله تعظيما، والسعي في الأرض قيل: هو في الصحراء،\nوقيل: هو في البلد أيضا، وهو الأصح.\nقال الحسن: الآية نزلت في المشركين المحاربين\nوالحكم مختص بهم، وقيل: نزلت في العرينيين، وذلك أن قوما من عرينة\n⟦4:335⟧\nأتو المدينة وأسلموا وأقاموا ما شاء الله ثم شكوا إلى النبي - صلى الله عليه وسلم - فاجتووا المدينة واستأذنوه في الخروج إلى لقاح الصدقة ليقيموا فيها إلى أن يصحوا وأذن لهبم ، فنالوا من ألبان اللقاح، وثابت قواهم، ثم ارتدوا، وقتلوا الرعاة، وساقوا اللقاح، فبعث رسول الله - صلى الله عليه وسلم - عليهم في طلبهم فأخذوا وقطعت أيديهم وأرجلهم، وسملت أعينهم، ولم تسلم دمائهم حتى ماتوا.\nوقيل: الآية في أهل العهد، وأكثر الفقهاء حملوا على المسلمين أيضا،\n⟦4:336⟧\nوجعل مالك: الإمام مخيرا فيمن سعى بالفساد من الأحكام الثلاثة،\nوقد روي ذلك عن ابن عباس. وجعل غيره الحكم ترتبا، وقال من قتل وأخذ المال قتل وصلب، وقتل فقط قيل لم يصلب. ومن أخذ المال\nفقط قطع يده ورجله من خلاف يده اليمنى ورجله اليسرى ولم يقتل\nومن لم يأخذ المال وإنما يخوف ينفى من الأرض، وذلك بأن يطلب.\n⟦4:337⟧\nفإن تاب قبل القدرة عليه عفي عنه، وإلا أخذ فحبس.\nوقيل: نفيه: طرده من بلد إلى بلد. روي ذلك\nعن ابن الزبير وعن ابن عبد العزيز،\nوقيل: الطلب، وقيل: القتل بعد القتل، ردعا لغيره، ونبه على تعظيم\nما ارتكبه أنه يجمع عليه حد الدنيا، وعقوبة الآخرة.\nقال عز وجل: (إلا الذين تابوا من قبل أن تقدروا عليهم فاعلموا أن الله غفور رحيم (34)\nالاستثناء راجع إلى كل من تقدم ذكره، وهو في العذاب\n⟦4:338⟧\nوفي إقامة الحدود، وقال بعض الفقهاء: كل حق لله مختص بقاطع\nالطريق فالتوبة قبل القدرة يزيل ما عليه إن كان من حقوق الله،\nوإن كان من حقوق الآدميين فلا يزول إذا طالب به صاحبه."}, {"a": [35], "v": 4, "p": 338, "ev": 4, "ep": 339, "sid": 1830, "t": "قوله عز وجل: (يا أيها الذين آمنوا اتقوا الله وابتغوا إليه الوسيلة وجاهدوا في سبيله لعلكم تفلحون (35)\nالوسيلة: القربة وهي دون الوصيلة،\nوقوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ﴾⟪5:35⟫ خطاب لكل من أظهر\nالإيمان سواء كان في مبدئه، أو في وسطه، أو في منتهاه.\nوتقوى الله: - هو الامتناع عن المحارم، وتحري الواجبات،\nوابتغاء الوسيلة، كما قال عليه الصلاة السلام حكاية عن الله عز وجل:\n⟦4:339⟧\n(ما زال العبد يتقرب إلي بالنوافل) الخبر.\nوالمجاهدة في سبيله: هو بذل الجهد فيما تقدم من إقامة الفرائض، وبين\nأنكم إذا فعلتم ذلك كنتم راجين للفلاح المذكور في قوله : ﴿قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ﴾⟪23:1⟫. والفلاح العام: هو البقاء بلا فناء، والغنى بلا فقر، والقدرة\nبلا عجز والعز بلا ذل. ونبه باختصاص لفظ الابتغاء على بذل الجهد."}, {"a": [36], "v": 4, "p": 339, "ev": 4, "ep": 340, "sid": 1831, "t": "قوله عز وجل: (إن الذين كفروا لو أن لهم ما في الأرض جميعا ومثله معه ليفتدوا به من عذاب يوم القيامة ما تقبل منهم ولهم عذاب أليم (36)\nأي لو حصل كل واحد ما في الأرض ومثله قاصدا\nبإحرازه أن يجعل ذلك وقاية لنفسه لم ينفعه، وذلك حث على المبادرة بالامتناع عن الآثام وترك الاهتمام بالمال في المعاد.\nوروى أنس عن النبي - صلى الله عليه وسلم - أنه يقال\n⟦4:340⟧\nللكافر يوم القيامة، أرأيت لو كان لك ملء الأرض ذهبا لكنت\nمفتديا به، فيقول: - نعم، فيقال له: كذبت، قد سئلت ما هو أهون من ذلك فأبيت) (1).\nوقوله: ﴿وَلَهُمۡ عَذَابٌ﴾⟪5:36⟫ الواو عطف، أو يكون بما بعد حال."}, {"a": [37], "v": 4, "p": 340, "ev": 4, "ep": 341, "sid": 1832, "t": "قوله عز وجل: (يريدون أن يخرجوا من النار وما هم بخارجين منها ولهم عذاب مقيم (37)\nأي يسألون أن يخرجوا منها، وذلك هو المذكور في قوله: ﴿أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا﴾⟪35:37⟫، والمقيم الذي لا يزول ولا يتحول،\nقال ابن عباس: كل شىء من أمر الدنيا يبلى ويفنى،\n⟦4:341⟧\nوكل شيء من أمر الآخرة يبقى ويتجدد.\nقوله تعالى: ﴿يُرِيدُونَ أَن يَخۡرُجُواْ﴾⟪5:37⟫ نبه بذلك على أنهم\nيحتالون لذلك ولا ينفعهم."}, {"a": [38], "v": 4, "p": 341, "ev": 4, "ep": 348, "sid": 1833, "t": "قوله عز وجل: (والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكالا من الله والله عزيز حكيم (38)\nالسارق: المتناول مال غيره مستترا،\nوقد يقال: للخائن سارق على التشبيه.\nوقول - صلى الله عليه وسلم -: (أسوأ الناس سرقة، الذي يسرق من صلاته) فعلى التشبيه.\nواختلف في الآية، فمنهم من قال: هو مجمل كقوله: ﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ﴾ وإجماله\n⟦4:342⟧\nمن حيث يحتاج إلى شرائط لا ينبئ الظاهر عنها.\nومنهم من قال: هو غير مجمل من حيث إنه يتناول لكل سارق،\nوما لم يرد منه فهو مخصص،\nوقال بعضهم: الألف واللام في (السارق والسارقة) للعهد.\nوالآية واردة في سارق المجن، وامرأة سرقت، لكن الحكم عام من حيث إنه قد ثبت أن حكم الشريعة في الواحد حكمها في\nالجماعة من شرطهم شرطه.\nوقال بعضهم: هو للجنس، وبعضهم جعلها بمعنى الذي، وذلك يتضمن معنى الشرط ويكون مفيدا للعموم.\n⟦4:343⟧\nوقراءة عامة القراء (السارق) بالرفع، وكان عيسى ينصب نحو قولهم زيدا\nفاضربه، والوجه الرفع؛ لأن النصب مختار حيث لا معنى للشرط، نحو زيدا\nفاضربه، فأما كل لفظ متضمن لمعنى الشرط فالرفع نحو قوله: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي﴾⟪24:2⟫، ونحو: (واللذان يأتيانها منكم).\nإن قيل: لم قدم المذكر في قوله: ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ﴾⟪5:38⟫\n⟦4:344⟧\nوأخر في قوله: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي﴾⟪24:2⟫؟\nقيل: لأن السرقة أكثر ما يوجد بالرجال، والزنا أكثر ما يوجد سببه من النساء، بل توهمنا امتناع انقياد المرأة أصل وجود الزنا.\nوبين أن الله تعالى عزيز في انتقامه، حكيم في حكمه.\nواختلف في قدر ما يقطع به، فروي عن عمر وعلي أنه يقطع في خمسة،\nوعن أبي سعيد الخدري في أربعة، وعن أبي بكر في ثلاثة،\nوعن ابن عباس في عشرة، وعن عائشة في ربع دينار،\nوإليه ذهب الشافعى، ومالك والحسن في\n⟦4:345⟧\nثلاثة، وقال أبو حنيفة: لا يقطع من يسرق طعاما\nيسرع إليه الفساد، أو ثيابا أوحديدا، أو قصبا، أو\nزرنيجا، ونورة، وقد روى: (ولا يقطع في ثمر ولا كثر)،\n⟦4:346⟧\nوقال الشافعي: ما لم يحرز فأما إذا أحرز وبلغ قيمته ما يقطع فيه\nقطع، وأما قدر القطع من اليد فعند الخوارج من المنكب وعند غيرهم من\nالرسغ.\nوقد روى أبو هريرة: (أن النبي - صلى الله عليه وسلم - قطع سارقا من\nالكوع).\n⟦4:347⟧\nولأن المقصد بقطعه أن لا يبطش، ولا يتناول بها، وبذلك يحصل\nالغرض، ولا يقطع إلا يمينها بدلالة قراءة ابن مسعود (فاقطعوا\nأيمانهما) فذلك يؤخذ به حكما، وإن لم يؤخذ به تلاوة.\nوإنما ذكر الأيدي بلفظ الجمع، وتارة بلفظ الاثنين، وتارة بلفظ الواحد كقول الشاعر: -\n⟦4:348⟧\nظهراهما مثل ظهور الترسين\nفذكر في موضع مثنى، وفي موضع مجموعا، وقال:\nكلوا في بعض بطنكم تصحوا\nفأتى بلفظ المفرد، ومتى كان شيئا لاثنين يصح اشتراكهما في أحدهما\nلا يصح أن يذكر إلا بلفظ التثنية، لئلا يشتبه نحو رأيت عبداكما ، ولا يصح إذا أردت الاثنين أن يقول: عبدكما أو عبيدكما."}, {"a": [39], "v": 4, "p": 348, "ev": 4, "ep": 349, "sid": 1840, "t": "قوله عز وجل: (فمن تاب من بعد ظلمه وأصلح فإن الله يتوب عليه إن الله غفور رحيم (39)\nقيل: إن تاب في الدنيا قبل القدرة عليه، وأصلح سقط عنه الحد، ورجى له الغفران، وإن تاب بعد القدرة عليه رجي له الغفران، ولم يسقط عنه الحد بدلالة ماروي ابن عمر: (أن امرأة سرقت على عهد رسول - صلى الله عليه وسلم -، فأمر بقطعها، فقال قومها: نحن نفديها خمسمائة دينار، فقال: اقطعوها، فقطعوا يمناها، فقالت المرأة: - هل لي من توبة يا رسول الله؟ قال: نعم، أنت اليوم في خطيئتك كيوم ولدتك أمك).\n⟦4:349⟧\nفأنزل الله ﴿فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ﴾⟪5:39⟫، ولم يقل: بعد سرقته، ليكون عاما في هذا الحكم، وفي غيره، واشترط إصلاح العمل تنبيها أن التوبة باللفظ غير مغنية ما لم يضامها ما يحققها من الفعل، وجعل علة قبول توبته كونه تعالى غفورا رحيما."}, {"a": [40], "v": 4, "p": 349, "ev": 4, "ep": 350, "sid": 1841, "t": "قوله عز وجل: (ألم تعلم أن الله له ملك السماوات والأرض يعذب من يشاء ويغفر لمن يشاء والله على كل شيء قدير (40)\nلما أمر بالتقوى، وابتغاء الوسيلة إليه بالجهاد في\nسبيله، ودعاهم إلى الفلاح وبين قبل ما يلزم المحاربين، وبعد ما يلزم\nالسراق، وذكر قبول توبتها، ذكر قدرته على تعذيب من يشاء، وغفران\nلمن يشاء في الدنيا بما شرعه، وفي الآخرة بما قدره.\nوقال ابن عباس: فيعذب من يشاء على الذنب الصغير،\nويغفر لمن يشاء على الذنب الكبير،\n⟦4:350⟧\nوفي هذا النحو قال الشاعر:\nيعفوا الملوك عن الكبير ... من الذنوب بفضلها\nولقدتعاقب في الصغير ... وليس ذاك بجهلها\nإلاليعرف فضلها ... ويخاف شدة ملكها\nوإنما قال يعذب من يشاء فقدم ذكر العقوبة على الغفران، لأن القصد بما\nتقدم الردع عن ارتكاب ما يقتضى عقوبة الدارين فكان تقديم ما يقتضي ذلك\nأولى."}, {"a": [41], "v": 4, "p": 350, "ev": 4, "ep": 355, "sid": 1842, "t": "قوله عز وجل: (يا أيها الرسول لا يحزنك الذين يسارعون في الكفر من الذين قالوا آمنا بأفواههم ولم تؤمن قلوبهم ومن الذين هادوا سماعون للكذب سماعون لقوم آخرين لم يأتوك يحرفون الكلم من بعد مواضعه يقولون إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيئا أولئك الذين لم يرد الله أن يطهر قلوبهم لهم في الدنيا خزي ولهم في الآخرة عذاب عظيم (41)\n⟦4:351⟧\nقيل: نزلت في أبي لبابة حيث بعثه رسول الله - صلى الله عليه وسلم -\nإلى السيدين، سيد الأوس وسيد الخزرج، سعد بن معاذ، وسعد بن\nعبادة، فاستشار قريظة أبا لبابة أننزل على حكم محمد؟ فأشار\nإليهم بأنه الذبح، قال أبو لبابة: فما زلت قدماي حتى علمت أني قد\nخنت الله ورسوله، والآية عني بها أبو لبابة والمنافقون الذين وصفهم في قوله:\n⟦4:352⟧\n(ألم تر إلى الذين نافقوا يقولون لإخوانهم الذين كفروا من أهل الكتاب لئن أخرجتم لنخرجن معكم ولا نطيع فيكم أحدا أبدا وإن قوتلتم لننصرنكم والله يشهد إنهم لكاذبون (11).\nوقوله: ﴿يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ﴾⟪5:41⟫ يكتسبونه عاجلا شيئا\nبعد شيء، على خلاف ما قال فيه: ﴿وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ﴾.\nوقوله: ﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾⟪3:133⟫.\nوقوله: ﴿سَمَّٰعُونَ لِلۡكَذِبِ﴾⟪5:41⟫ أي قائلون له، وقيل: سماعون كلامك\nلأجل أن يكذبوا عليك، ويسمعون ذلك لأجل قوم آخرين.\nوقوله: ﴿يُحَرِّفُونَ ٱلۡكَلِمَ﴾⟪5:41⟫ أي كلام النبي - صلى الله عليه وسلم -، والقرآن، ويكذبون عليه.\n⟦4:353⟧\nوقيل: يحرفون حكم التوراة، وذلك كقوله في البقرة: ﴿أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ﴾⟪2:75⟫ إلى قوله: ﴿وَهُمۡ يَعۡلَمُونَ﴾\nوقوله في آل عمران: (وقالت طائفة من أهل الكتاب آمنوا بالذي أنزل على الذين آمنوا وجه النهار واكفروا آخره لعلهم يرجعون (72) ولا تؤمنوا إلا لمن تبع دينكم).\nوقوله: (هذا) أي الحكم الذي قلناه، وقيل: الدية.\nوقوله: ﴿مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ﴾⟪5:41⟫ أي من بعد أن وضعه الله موضعه، وبين أحكامه.\n⟦4:354⟧\nوقوله: ﴿وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ﴾⟪5:41⟫ أي أمركم محمد بغير ذلك فاحذروه.\nوقوله: ﴿وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ﴾⟪5:41⟫ قال الحسن: عذابه كقوله: ﴿يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ﴾⟪51:13⟫.\nوقال السدي: ضلالة. وقال الزجاج: فضحيته\nوقوله: ﴿لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ﴾⟪5:41⟫ أي من الكفر عقوبة لهم،\nوقيل: لم يحكم بطهارة قلوبهم.\nوالقولان مرادان على نحو ما تقدم من أمثال هذه الآية.\nوذلك بخلاف من وصفهم بقوله: (إنما يريد الله ليذهب عنكم الرجس أهل البيت ويطهركم تطهيرا (33).\n⟦4:355⟧\nوقوله: (إنهم فتية آمنوا بربهم وزدناهم هدى (13).\nوقد قال: ﴿فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ﴾⟪6:125⟫.\nوقوله تعالى: ﴿لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ﴾⟪5:41⟫ أي يستحي منه من السبي والقتل والجلاء."}, {"a": [42], "v": 4, "p": 355, "ev": 4, "ep": 358, "sid": 1847, "t": "قوله عز وجل: (سماعون للكذب أكالون للسحت فإن جاءوك فاحكم بينهم أو أعرض عنهم وإن تعرض عنهم فلن يضروك شيئا وإن حكمت فاحكم بينهم بالقسط إن الله يحب المقسطين (42)\nالسحت والمحق متقاربان معنى، لتقارب لفظيهما.\nلكن السحت أبلغ إذ هو الاستئصال شيئا فشيئا يقال: سحته\n⟦4:356⟧\nفأسحته، وسمي الحرام والمستقبح من الكسب والوخيم العاقبة منه سحتا، كما سمي الحرام نارا في قوله: ﴿إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ﴾⟪4:10⟫، وفسر\nالسحت هاهنا بالرشوة تفسير العام بالخاص.\nوقد قال عليه الصلاة والسلام: (هدايا الآمراء من السحت).\nوالمقصود من الآية مثل ما قاله: ﴿يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ﴾⟪2:79⟫.\nوقيل: عنى بالسحت الربا، المذكور في قوله:\n⟦4:357⟧\n(فبظلم من الذين هادوا حرمنا عليهم طيبات أحلت لهم وبصدهم عن سبيل الله كثيرا (160) وأخذهم الربا وقد نهوا عنه).\nواختلف في قوله: ﴿فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ﴾⟪5:42⟫، فقال: ابن عباس: -\nنسخ بقوله: ﴿وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ﴾⟪5:49⟫ فجعل حكم التخيير\nمنسوخا بإيجاب الحكم بينهم.\nوقال الشعبي: بل حكمه ثابت.\nوقوله: ﴿وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ﴾⟪5:49⟫ حث على\nاستعمال العدالة عند تولي\n⟦4:358⟧\nالحكم لا إيجاب وعلى هذا قال الحسن: خلوا بين أهل الكتاب وحاكمهم\nوإذا ترافعوا إليكم فاحكموا بينهم بما في كتابكم.\nوقال بعضهم: التخيير قبل أن (يعقد) لهم الدية والجزية، والإيجاب ﴿وَأَنِ ٱحۡكُم بَيۡنَهُم﴾⟪5:49⟫ بعد عقد الدية لهم بالجزية.\nوقد روي ذلك عن ابن عباس قال: ويدل أن الآية نزلت في\nبني قريظة والنضير ولم يكن لهم ذمه."}, {"a": [43], "v": 4, "p": 358, "ev": 4, "ep": 359, "sid": 1850, "t": "قوله عز وجل: (وكيف يحكمونك وعندهم التوراة فيها حكم الله ثم يتولون من بعد ذلك وما أولئك بالمؤمنين (43)\nأنكر الله تعالى تحكيمهم للنبي - صلى الله عليه وسلم - وهم لا يؤمنون به وعندهم الحكم في التوراة، والمعنى هاتين الحالتين\n⟦4:359⟧\nمستنكر بتحكيمهم إياك،\nوقوله ﴿وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ﴾⟪5:43⟫ أي لا يصدقونك فيما تحكم به،\nوالواو واو حال."}, {"a": [44], "v": 4, "p": 359, "ev": 4, "ep": 363, "sid": 1851, "t": "وقوله عز وجل: (إنا أنزلنا التوراة فيها هدى ونور يحكم بها النبيون الذين أسلموا للذين هادوا والربانيون والأحبار بما استحفظوا من كتاب الله وكانوا عليه شهداء فلا تخشوا الناس واخشون ولا تشتروا بآياتي ثمنا قليلا ومن لم يحكم بما أنزل الله فأولئك هم الكافرون (44)\nالهدى والنور إشارة إلى معنى واحد، لكن الهدى يقال\nاعتبارا بالأدلة المنصوبة، والنور اعتبارا بما يعين على معرفة الأدلة، تشبيها بنور البصر، ونور الشمس.\nوقيل: الهدى إشارة إلى ما فيه من الحكم\nالشرعي، والنور إشارة إلى ما فيه من الحكم العقلي،\nوقد يسمى كل واحد من المعقول والمشروع تارة نورا وتارة هدى.\nإن قيل: ما معنى قوله: ﴿ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ﴾⟪5:44⟫ والنبي لا يكون غير مسلم؟\nقيل: الإسلام هاهنا الإخلاص لله في التوكل عليه وتفويض الأمر إليه، نحو قوله:\n⟦4:360⟧\n(إذ قال له ربه أسلم قال أسلمت لرب العالمين (131).\nوقوله: ﴿وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ﴾⟪31:22⟫.\nوقوله حكاية عن إبراهيم وإسماعيل: ﴿رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾⟪2:128⟫.\nوقوله: ﴿ٱلَّذِينَ أَسۡلَمُواْ﴾⟪5:44⟫ صفة لهم على سبيل المدح لا على\nسبيل التخصيص، أو بدل من قوله: (النبيون)، واللام في قوله:\n﴿لِلَّذِينَ هَادُواْ﴾⟪5:44⟫ متعلق بقوله: ﴿إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ﴾⟪5:44⟫ ... للذين هادوا.\nوقيل: متعلق بقوله: ﴿فِيهَا هُدٗى﴾⟪5:44⟫ ومعنى هادوا: أي تابوا\n⟦4:361⟧\nمن قوله: ﴿إِنَّا هُدۡنَآ إِلَيۡكَۚ﴾⟪7:156⟫.\nوقيل تقديره: يحكم بها النبيون الذين هادوا، والمعنى يحكم لهم وعليهم، لكن المعنى تذكيرهم عن داعيهم وعلى هذا قال بعضهم: يحكم فيهم، لأن قولك فيهم يتضمن معنى وعليهم،\nوقوله: ﴿بِمَا ٱسۡتُحۡفِظُواْ﴾⟪5:44⟫ قيل: متعلق بالأحبار، أي العلماء بما استحفظوا، وقيل: متعلق بقوله: ﴿يَحۡكُمُ بِهَا﴾⟪5:44⟫ لأجل ما استحفظوا أي لما استودعوا، وقوله: ﴿وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ﴾⟪5:44⟫ أي هم من جملة من قال فيهم: ﴿وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ﴾⟪39:69⟫،\nوقوله: ﴿وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ﴾⟪5:44⟫\nيتعلق به الخوارج، وزعموا أن التارك\n⟦4:362⟧\nلحكم الله على كل حال كافر، وقال غيرهم: ومن لم يحكم بما أنزله جاحدا فهو كافر، وقيل معناه: من لم يحكم بأن ذلك عامدا له فهو كافر، وقيل:\nالكافر هاهنا جاحد للنعمة من الكفران لا من الكفر،\nوقيل: الكفر يقال على ضربين: كفركبير، وهو المذكور في قوله: ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ﴾⟪4:136⟫ الآية.\nوكفر صغير وهو المذكور في قوله عليه الصلاة والسلام:\n(من ترك الصلوات فقد كفر)، وعلى هذا قال ابن جريج: كفر دون كفر،\n⟦4:363⟧\nوظلم دون ظلم، وفسق دون فسق، قال الحسن: إن الله تعالى أوجب على الحكام ثلاثا، أن لا تتبعوا الهوى، وأن تخشوه ولا تخشوا الناس، وأن لا تشتروا بآياتي ثمنا قليلا، قال وعلى هذا قوله: ﴿يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ﴾⟪38:26⟫.\nوقد استدل بهذه الآية أن النبي - صلى الله عليه وسلم -\nمتعبد بأحكام من قبله."}, {"a": [45], "v": 4, "p": 364, "ev": 4, "ep": 367, "sid": 1856, "t": "قوله عز وجل: (وكتبنا عليهم فيها أن النفس بالنفس والعين بالعين والأنف بالأنف والأذن بالأذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفارة له ومن لم يحكم بما أنزل الله فأولئك هم الظالمون (45)\nأخبر تعالى بما أوجب عليه من القصاص.\nواتفق الفقهاء: أن ذلك واجب علينا لوجوبه عليهم، لكن منهم\nمن قال: لم يكن في شريعتهم الدية، وقد جعلها في شريعتنا تخفيفا على هذه الأمة،\nوقوله: ﴿وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ﴾⟪5:45⟫ يقتضي القود فيه فقاءا كان أو إذهابا بضوئها.\nومن قال لا يفعل من ذلك إلا الفقاء فليس بشىء، فالعين ليست بالعين في الحقيقة إذا لم تكن مبصرة بل بالأعضاء كلها إذا بطلت منفعتها خرجت عن أن تكون في\n⟦4:365⟧\nالحقيقة إياه إلا اعتبار الصورة التخطيطية، وذلك غير معتد به ما لم يكن فيه\nالنفع.\nواختلف الصحابة في عين الأعور، وهل يلزم فيه القود ودية كاملة.\nفمنهم من أوجب ذلك فيها لكونها سادة مسد العينين.\nوالأنف يلزم فيها القصاص بالقطع.\nوقال أبو حنيفة: إذا قطع الأنف من أصله فلا قصاص لأنه\nلا يمكن اسشيفاؤه فيه كما لو قطع يده من نصف الساعد.\nوقوله: ﴿وَٱلۡجُرُوحَ قِصَاصٞۚ﴾⟪5:45⟫ إيجاب للقصاص في سائر الجراحات،\nوقرئ: ﴿وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ﴾⟪5:45⟫ بالرفع كقولك: إن زيدا منطلق، وعمروا ذاهب.\n⟦4:366⟧\nوقوله: (والجروح) إذا قرئ بالنصب فعلى العطف، وإذا قرئ\nبالرفع فعلى الاستئناف،\nوقوله: ﴿فَمَن تَصَدَّقَ بِهِۦ﴾⟪5:45⟫ خطاب لولي القتيل وللجروح حث له على العفو، وذكر لفظ التصدق تنبيها على أن عفوه جار مجرى صدقة يستحق بها ثواب، وتصير كفارة له، وذكر هاهنا أن تارك الحكم بما أنزله ظالم، والظلم أعم من الكفر، لأن كل كافر ظالم وليس كل ظالم كافرا.\n⟦4:367⟧\nولذلك قال: ﴿إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ﴾⟪31:13⟫."}, {"a": [46, 47], "v": 4, "p": 367, "ev": 4, "ep": 368, "sid": 1859, "t": "وقوله عز وجل: (وقفينا على آثارهم بعيسى ابن مريم مصدقا لما بين يديه من التوراة وآتيناه الإنجيل فيه هدى ونور ومصدقا لما بين يديه من التوراة وهدى وموعظة للمتقين (46) وليحكم أهل الإنجيل بما أنزل الله فيه ومن لم يحكم بما أنزل الله فأولئك هم الفاسقون (47)\nقفيناه: بعثناه خلفه، يقفوه: أي يتبع قفاه، ومنه قافية الشعر، والقفي: الضيف الذي يبعث خلفه تكرمه له، والأثر: ما يظهر للحاسة، والإثار الاختيار، واستثاره اختاره لنفسه،\nوالهدى: يقال لما يستدل به، والموعظة لما يوعظ به، والفسق أعظم\n⟦4:368⟧\nمن الكفر والظلم، وأصله الخروج إلى حظر الله، من قوله: فسقت\nالرطبة إذا خرجت عن طلعها.\nإن قيل: لم كرر قوله: ﴿مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ﴾⟪5:46⟫؟\nقيل: يجوز أنه أراد بالأول مصدقا لما بين يدي التوراة، وبالثاني نفس التوراة، فبين أن عيسى عليه الصلاة والسلام أتى بما يصدق به موسى، وكتابه أتى بما يصدق كتاب موسى."}, {"a": [48], "v": 4, "p": 368, "ev": 4, "ep": 372, "sid": 1860, "t": "قوله عز وجل: (وأنزلنا إليك الكتاب بالحق مصدقا لما بين يديه من الكتاب ومهيمنا عليه فاحكم بينهم بما أنزل الله ولا تتبع أهواءهم عما جاءك من الحق لكل جعلنا منكم شرعة ومنهاجا ولو شاء الله لجعلكم أمة واحدة ولكن ليبلوكم في ما آتاكم فاستبقوا الخيرات إلى الله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون (48)\n⟦4:369⟧\nالمهيمن: قيل الحفيظ، وقيل الرقيب، وقيل: الأمين ، وقيل: الشاهد،\nقال أبو عبيدة: الحاذق في علمه، وقال ابن عيينه: أصله مؤيمن فقلبت همزة هاء، كما قالوا: - أهرقت في قولهم أرقت، وقد قيل: همين يهمينه. وحقيقة المعنى أنه جعل هذا الكتاب حافظا ومستوليا لسائر ما تقدم من كتبه يحكم عليها وهي لا حكم عليه، وينسخها وهي لا تنسخه، وصح على هذا: ﴿مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ﴾⟪2:106⟫، يعني ما ننسخ من\n⟦4:370⟧\nالكتب المتقدمة ﴿نَأۡتِ بِخَيۡرٖ مِّنۡهَآ﴾⟪2:106⟫، يعني من الكتاب العربي.\nوالشرعة والشريعة: في الأصل الطريقة الظاهرة التي يتوصل بها إلى الماء ثم استعملت فيما شرعه الله لعبادة من (1) الدين الذي يوصل إلى الحياة الأبدية، كما سمى كتابه المهيمن على ما تقدم.\nومن أصله: أشرعت القباء وشرعت في الماء، وهم شرع.\nوالمنهاج: الطريق المستقيم، يقال: طريق نهج ومنهج.\nإن قيل: ما الفرق بين الشرعة والمنهاج؟\nقيل: قال بعضهم: الشرعة إشارة إلى الدين وهو الشرع، والمنهاج: إشارة إلى الدليل الذي يتوصل إلى معرفته والتخصيص به،\nوقد روي عن ابن عباس أنه قحال: شرعة ومنهاجا: دينا وسبيلا.\nإن قيل: كيف قال: ﴿لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ﴾⟪5:48⟫ فاقتضى ذلك أن\n⟦4:371⟧\nلكل واحد من الأنبياء شريعة غير شريعة الآخر، وقال في موضع:\n﴿شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ﴾⟪42:13⟫.\nفذكر أنه شرع لجميعهم شريعة واحدة.\nقيل: الذي استوى فيه شريعة جماعه هو أصول الإيمان والإسلام، أعني التوحيد والصلاة والزكاة والصوم والقرابين، فإن أصول هذه الأشياء لا ينفك منها شرع بوجه، وأما الذي ذكر أنه تفرد به كل واحد من الأنبياء فروع العبادات من كيفياتها وكمياتها، فإن ذلك مشروع على حسب مصالح كل أمة، وعلى مقتضى الحكمة من الأزمنة المختلفة،\nووجه آخر: أن الشرائع إذا عتبرت بالشارع\n⟦4:372⟧\nفمقتضى حكمته يصح أن كلها واحدة، وكذا إذا اعتبرت لغرض والقصد الذي هو مصلحة المشروع له وإذا اعتبرت بذوات الأفعال فهي شرائع كثيرة، وعلى هذين النظريتين، قال الله تعالى: ﴿وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۭ بِٱلۡبَصَرِ﴾⟪54:50⟫، وقال في موضع آخر: ﴿كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ﴾⟪55:29⟫،\nوقوله: ﴿وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ﴾⟪5:48⟫، كقوله: (يا داوود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله إن الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب (26)."}, {"a": [49], "v": 4, "p": 372, "ev": 4, "ep": 374, "sid": 1864, "t": "قوله عز وجل: (وأن احكم بينهم بما أنزل الله ولا تتبع أهواءهم واحذرهم أن يفتنوك عن بعض ما أنزل الله إليك فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم وإن كثيرا من الناس لفاسقون (49)\nقوله: ﴿وَأَنِ ٱحۡكُم﴾⟪5:49⟫ فهو معطوف على معنى الكتاب، وقوله: (مصدقا) إلى قوله: ﴿فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ﴾⟪5:48⟫\n⟦4:373⟧\nأي أنزلنا بأن احكم.\nوقيل: من الواجب أن احكم، والأول أوجه، لأنه لا يقع أن افعل إذا كان بعده أمر إلا من موقع المصدر.\nويتقارب فتله عن كذا.\n(فتنة) ولكن فتنه يقال في الصرف عن الخير والشر، وفتله يقال في الصرف عن الخير.\nإن قيل: لم قال: ﴿أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ﴾⟪5:49⟫ فخص البعض؟ قيل في ذلك أوجه: الأول: أنه عنى بذلك الكفر والنفاق الذي لا غفران فيه، لكن ذكر البعض منها يكون أردع للعباد.\nوالثاني: لأنه ذكر البعض للمبالغة تنبيها على أنه\nإذا أصابهم ببعض الذنوب يقال في كل أولى.\nإن قيل: لما كرر ﴿وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ﴾⟪5:49⟫؟\nقيل: قال بعضهم: إن ذلك في حكمين:\nحكم في المحصن، وحكم قتيل كان فيهم، ففرق كل واحد منهما نهي عن\n⟦4:374⟧\nالهوى، تنيبها أن الهوى لا يسفر عن نجاح ولا في صلاح.\nوقال بعضهم: - تقدير الكلام أنزلنا إليك الكتاب بالحق، وبأن احكم\nبما أنزل، وبأن لا تتبع الهوى، فاحكم بما أنزل الله ولا تتبع الهوى فأخبر بإنزال ذلك أولا، ثم أمر به أمرا مجزما، وقدم الأمر على الإخبار عن الأمر به\nتأكيدا، وتقدير الكلام: - قد أوجبت عليك الحكم بذلك، وترك إتباع الهوى فاحكم بذلك."}, {"a": [50], "v": 4, "p": 374, "ev": 4, "ep": 375, "sid": 1866, "t": "قوله عز وجل: (أفحكم الجاهلية يبغون ومن أحسن من الله حكما لقوم يوقنون (50)\nأنكر عليهم تحريهم الجاهلية وتركهم لحكم الله، ثم قال: ﴿وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ﴾⟪5:50⟫.\nتنبيها أن ذلك يعلمه الموقن،\nوقوله: (لقوم) قيل: عند قوم،\n⟦4:375⟧\nوقيل: أراد لقوم (يوقنون) عليهم، فدل مالهم على ما عليهم.\nإن قيل: كيف يكون حكم أحسن من حكم إذا كانا حقين؟\nقد يحكم أحد الحاكمين بعلم يحكم الآخر بغلبة ظن، وكلاهما حسنان، والأول أحسن، وقد يجتهدان في حكمين وأحدهما أقرب إلى الحكم نحو اجتهاد داوود وسليمان."}, {"a": [51], "v": 4, "p": 375, "ev": 4, "ep": 376, "sid": 1867, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى أولياء بعضهم أولياء بعض ومن يتولهم منكم فإنه منهم إن الله لا يهدي القوم الظالمين (51)\nالاتخاذ الاعتماد هاهنا، وأصله افتعال من الأخذ، والأخذ حوز الشيء وذلك تارة بالتناول، وتارة بالاعتماد عليه، وتارة بالإهلاك نحو: ﴿فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ﴾⟪79:25⟫.\nالآية، نزلت في عبادة بن الصامت، وعبد الله بن أبي\n⟦4:376⟧\nلما تبرأ عبادة من مولاة اليهود، وتمسك عبد الله بها وقال أخاف الدوائر.\nوقيل: نزلت في أبي لبابة بن المنذر لما نصح لليهود وأشار بأنه الذبح،\nوقال ابن عباس والحسن: إنها نزلت في نصارى بني تغلب\nقال قوم إنهم كبني إسرائيل في جواز أكل ذبائحهم، لأنه قال: ﴿فَإِنَّهُۥ مِنۡهُمۡۗ﴾⟪5:51⟫."}, {"a": [52], "v": 4, "p": 376, "ev": 4, "ep": 377, "sid": 1868, "t": "قوله عز وجل: (فترى الذين في قلوبهم مرض يسارعون فيهم يقولون نخشى أن تصيبنا دائرة فعسى الله أن يأتي بالفتح أو أمر من عنده فيصبحوا على ما أسروا في أنفسهم نادمين (52)\n⟦4:377⟧\nأي ترى المنافقين يسارعون في الدخول في جملتهم،\nوقيل: يسارعون في مرضاتهم،\nوالدائرة: دوران الأمر من قولهم والدهر بالإنسان دواري.\nوالدورة والدولة يتقاربان،\nوالفتح قيل فتح مكة، وقيل: بل نفعا أتى من الله.\nوالأمر هاهنا واحد الأمور يأتي بأمر لا يعرفون سببه ووجه إلزامهم في ذلك أن الأمور ضربان: واجب، وممكن، وما وعد الله تعالى من نصرة المؤمنين فواجب كونه أي صادق الوجود. يقال: هب أن لك ليس من الواجب إما جعلتموه من الممكنات التي عسى أن تكون، فأخبر أن المنافقين يميلون إلى الكفار ويقولون لا نأمن أن تكون لهم دولة على أصحاب محمد - صلى الله عليه وسلم -، وذلك لقلة إيمانهم بما ضمن الله من نصرة المؤمنين وقال تعالى: ﴿فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ﴾⟪5:52⟫ على ما فعلوه، ونبه أنه يأتيهم بذلك، فإن عسى منه واجب."}, {"a": [53], "v": 4, "p": 377, "ev": 4, "ep": 379, "sid": 1869, "t": "قوله تعالى: (ويقول الذين آمنوا أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم حبطت أعمالهم فأصبحوا خاسرين (53)\n⟦4:378⟧\nأي أقسموا أن يوالوكم على الكفار، ولم يفعلوا،\nوقوله: ﴿جَهۡدَ أَيۡمَٰنِهِمۡ﴾⟪5:53⟫ أي أبلغ الإيمان وأقصاها من قولهم جهد\nفي الأمر ونصبه على المصدر،\nوقوله: ﴿حَبِطَتۡ أَعۡمَٰلُهُمۡ﴾⟪5:53⟫ يصح أن يكون معطوفا على ما حكى عن الذين آمنوا، ويصح أن يكون استئناف كلام من الله على طريق الإخبار،\nوعلى طريق الدعاء عليهم.\nوإذا قرأ: ﴿وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ﴾⟪5:53⟫ فتقديره: عسى الله أن يأتي بالفتح، وأن يقول الذين آمنوا.\nوقرأه أهل المدينة، يقول الذين آمنوا بغير الواو.\n⟦4:379⟧\nوإنما قال: ﴿فَأَصۡبَحُواْ خَٰسِرِينَ﴾⟪5:53⟫ فخص لفظ الإصباح لأمرين:\nأحدهما: لما كان أكثر محاربتهم وغاراتهم وقت الصباح كثر عبارتهم عن التغيرات وعلى هذا قول الشاعر:\nيا راقدا الليل مسرورا بأوله ... إن الحوادث قد يطرقن أسحارا\nوالثاني: أنه لما كان بالإصباح انتهاء الظلمة، وانتشار الأشعة، وظهور ما كان بالليل مستترا خص (فأصبحوا) تنبيها على زوال غمة الجهالة وظهور الخفاء كقولهم فى المثل لما يظهر: بزغ الخفاء بداء الصبح لذي العينين،\nونحو ذلك."}];
